app.use((req,res,next)=>{
  const [pathname,...queryParts]=String(req.url||'').split('?');
  const normalizedPath=pathname.replace(/\/{2,}/g,'/');
  if(normalizedPath!==pathname) req.url=normalizedPath+(queryParts.length?`?${queryParts.join('?')}`:'');
  next();
});
