const krispMcp = createKrispMcpService({
  url:KRISP_MCP_URL,
  fallbackAccessToken:KRISP_MCP_ACCESS_TOKEN,
  resolveSecret:async(provider,credentialType,fallback='')=>{
    if(String(provider||'').toLowerCase()==='krisp'&&['access_token','api_key'].includes(String(credentialType||''))){
      return resolveKrispAccessToken(fallback);
    }
    return resolveIntegrationSecret(provider,credentialType,fallback);
  },
  logger:console,
  timeoutMs:30000
});

function inferValOwner(obj={}){
  const ids = [
    obj.assignedTo,
    obj.assignedUserId,
    obj.userId,
    obj.ownerId,
    obj.contact?.assignedTo,
    obj.contact?.assignedUserId,
    obj.contact?.userId
  ].filter(Boolean).map(String);
  const raw = [
    obj.assignedTo,
    obj.assignedToName,
    obj.assignedUserName,
    obj.userName,
    obj.ownerName,
    obj.contactOwner,
    obj.user?.name,
    obj.assignedUser?.name,
    obj.contact?.assignedTo,
    obj.contact?.assignedToName,
    obj.contact?.assignedUserName
  ].filter(Boolean).join(' ');
  return raw ? raw.trim() : (ids.length ? 'Assigned user' : '');
}

