async function getTeachValSession(id=''){
  await valDbReady;
  if(pgPool){
    const args=[tenantId(),currentUserId()];
    let where='tenant_id=$1 and user_id=$2';
    if(id){args.push(id);where+=' and id=$3';}
    const r=await dbQuery(`select * from teach_val_onboarding_sessions where ${where} order by updated_at desc limit 1`,args);
    return teachValSessionRow(r.rows[0]);
  }
  const {rows}=teachValStoreArray('teachValOnboardingSessions');
  const found=rows.filter(r=>r.tenantId===tenantId()&&r.userId===currentUserId()&&(!id||r.id===id)).sort((a,b)=>new Date(b.updatedAt||0)-new Date(a.updatedAt||0))[0];
  return teachValSessionRow(found);
}
async function getTeachValWitnessingResumeSession(){
  await valDbReady;
  if(pgPool){
    const r=await dbQuery(`select s.* from teach_val_onboarding_sessions s
      where s.tenant_id=$1 and s.user_id=$2 and s.status in ('draft','committed')
      and exists (
        select 1 from teach_val_imports i
        where i.tenant_id=s.tenant_id and i.user_id=s.user_id and i.session_id=s.id and i.category like 'witness_%'
      )
      order by case when s.status='draft' then 0 else 1 end, s.updated_at desc limit 1`,[tenantId(),currentUserId()]);
    return teachValSessionRow(r.rows[0]);
  }
  const {rows:sessions}=teachValStoreArray('teachValOnboardingSessions');
  const {rows:imports}=teachValStoreArray('teachValImports');
  const found=sessions
    .filter(r=>r.tenantId===tenantId()&&r.userId===currentUserId()&&['draft','committed'].includes(r.status))
    .filter(r=>imports.some(i=>i.tenantId===tenantId()&&i.userId===currentUserId()&&i.sessionId===r.id&&String(i.category||'').startsWith('witness_')))
    .sort((a,b)=>{
      if(a.status!==b.status) return a.status==='draft'?-1:1;
      return new Date(b.updatedAt||0)-new Date(a.updatedAt||0);
    })[0];
  return teachValSessionRow(found);
}
async function teachValWitnessingSessionIsComplete(session){
  if(!session?.id) return false;
  const state=normalizeTeachValState(session.state||{});
  const imports=await listTeachValImports(session.id).catch(()=>[]);
  const hasFinalCard=imports.some(i=>String(i.category||'')==='witness_partnership_agreement' && !/Needs Clarification/i.test(String(i.status||'')));
  return state.stage==='complete' && hasFinalCard;
}
async function saveTeachValSession(session){
  await valDbReady;
  const clean=teachValSessionRow(session);
  clean.updatedAt=new Date().toISOString();
  if(pgPool){
    await dbQuery(`insert into teach_val_onboarding_sessions (id,tenant_id,user_id,status,state_json,created_at,updated_at)
      values ($1,$2,$3,$4,$5,coalesce($6::timestamptz,now()),now())
      on conflict (id) do update set tenant_id=excluded.tenant_id,user_id=excluded.user_id,status=excluded.status,state_json=excluded.state_json,updated_at=now()`,[clean.id,clean.tenantId,clean.userId,clean.status,JSON.stringify(clean.state),clean.createdAt]);
    return getTeachValSession(clean.id);
  }
  const {store,rows}=teachValStoreArray('teachValOnboardingSessions');
  const idx=rows.findIndex(r=>r.id===clean.id);
  const row={id:clean.id,tenantId:clean.tenantId,userId:clean.userId,status:clean.status,state:clean.state,createdAt:clean.createdAt,updatedAt:clean.updatedAt};
  if(idx>=0)rows[idx]=row;else rows.unshift(row);
  saveValStore(store);
  return teachValSessionRow(row);
}
