app.post('/api/auth/login',async(req,res)=>{
  await valDbReady;
  const email=String(req.body.email||'').trim().toLowerCase();
  authLog('login requested',{email});
  const user=await findUserByEmail(email)||await createOwnerUserForEmail(email);
  if(!user){authLog('login failed: unknown email',{email});await auditLog({req,tenantId:tenantId(),userId:'',action:'login',resourceType:'user',metadata:{email,reason:'unknown_email'},success:false}).catch(()=>{});return res.status(401).json({ok:false,error:'Invalid email or password'});}
  if(!user.passwordHash){
    const adminPassword=String(process.env.ADMIN_PASSWORD||'');
    if(adminPassword&&isOwnerLoginEmail(email)&&String(req.body.password||'')===adminPassword){
      const repairedHash=await hashPassword(adminPassword);
      await setUserPassword(user.id,repairedHash);
      user.passwordHash=repairedHash;
      authLog('login filled owner password from env',{email,userId:user.id});
    }else{
      authLog('login requires password setup',{email,userId:user.id});
      return res.status(403).json({ok:false,requiresPasswordSetup:true,message:'Password setup required'});
    }
  }
  if(!(await verifyPassword(req.body.password,user.passwordHash))){
    const adminEmail=String(process.env.ADMIN_EMAIL||'').trim().toLowerCase();
    const adminPassword=String(process.env.ADMIN_PASSWORD||'');
    if(adminPassword&&isOwnerLoginEmail(email)&&String(req.body.password||'')===adminPassword){
      await setUserPassword(user.id,await hashPassword(adminPassword));
      authLog('login repaired admin password from env',{email,userId:user.id});
    }else{
      authLog('login failed: bad password',{email,userId:user.id});
      await auditLog({req,tenantId:tenantId(),userId:user.id,action:'login',resourceType:'user',resourceId:user.id,metadata:{email,reason:'bad_password'},success:false}).catch(()=>{});
      return res.status(401).json({ok:false,error:'Invalid email or password'});
    }
  }
  const sessionId=await createSession(user.id,req);
  setSessionCookie(res,sessionId);
  authLog('login succeeded',{email,userId:user.id});
  await auditLog({req,tenantId:tenantId(),userId:user.id,action:'login',resourceType:'user',resourceId:user.id,metadata:{email},success:true}).catch(()=>{});
  res.json({ok:true,user:publicUser(user),redirectUrl:'/dashboard'});
});
app.post('/api/auth/request-password-setup',async(req,res)=>{
  await valDbReady;
  const email=String(req.body.email||'').trim().toLowerCase();
  const generic={ok:true,message:'If that email exists, a setup link has been created.'};
  authLog('password setup requested',{email,hasEmail:!!email});
  if(!email) return res.status(400).json({ok:false,error:'Email is required'});
  const user=await findUserByEmail(email)||await createOwnerUserForEmail(email);
  if(!user){
    authLog('password setup requested for unknown email',{email});
    return res.json(generic);
  }
  const token=passwordSetupToken();
  const expiresAt=new Date(Date.now()+60*60*1000).toISOString();
  await storePasswordSetupToken(user.id,hashPasswordSetupToken(token),expiresAt);
  const setupUrl=passwordSetupUrlForRequest(req,token);
  authLog('password setup token generated',{email,userId:user.id,expiresAt,tokenHashPrefix:hashPasswordSetupToken(token).slice(0,10),setupUrlHost:new URL(setupUrl).host});
  res.json({...generic,setupUrl,expiresAt});
});
app.post('/api/auth/set-password',async(req,res)=>{
  await valDbReady;
  const token=String(req.body.token||'');
  const password=String(req.body.password||'');
  authLog('set password requested',{hasToken:!!token,passwordLength:password.length});
  if(!token){authLog('set password failed: missing token');return res.status(400).json({ok:false,error:'Invalid or expired setup link'});}
  if(password.length<10){authLog('set password failed: short password');return res.status(400).json({ok:false,error:'Password must be at least 10 characters'});}
  const user=await findUserByPasswordSetupToken(token);
  if(!user){authLog('set password failed: invalid or expired token',{tokenHashPrefix:hashPasswordSetupToken(token).slice(0,10)});return res.status(400).json({ok:false,error:'Invalid or expired setup link'});}
  await setUserPassword(user.id,await hashPassword(password));
  const sessionId=await createSession(user.id,req);
  setSessionCookie(res,sessionId);
  authLog('set password succeeded',{email:user.email,userId:user.id});
  await auditLog({req,tenantId:tenantId(),userId:user.id,action:'login',resourceType:'user',resourceId:user.id,metadata:{method:'set_password'},success:true}).catch(()=>{});
  res.json({ok:true,user:publicUser(user),redirectUrl:'/dashboard'});
});
