async function tenantOpenAIConnectionReadiness(){
  const [row,secret]=await Promise.all([
    getTenantApiKeyRow('openai').catch(()=>null),
    getTenantApiKeySecret('openai').catch(()=> '')
  ]);
  const saved=normalizeTenantApiKeyRow(row);
  const keyLooksValid=tenantApiKeyLooksValid('openai',secret);
  return {
    connected:!!(keyLooksValid&&saved?.status==='connected'),
    status:saved?.status||'not_connected',
    lastUpdatedAt:saved?.lastUpdatedAt||'',
    lastTestedAt:saved?.lastTestedAt||''
  };
}
async function witnessingOpenAIReadiness(){
  const [openai,resumableSession]=await Promise.all([
    tenantOpenAIConnectionReadiness(),
    getTeachValWitnessingResumeSession().catch(()=>null)
  ]);
  const continuationAllowed=!!resumableSession?.id;
  return {
    ok:true,
    openai,
    continuationAllowed,
    requiresOpenAIKey:!openai.connected&&!continuationAllowed
  };
}
async function requireOpenAIForNewWitnessing(res){
  const readiness=await witnessingOpenAIReadiness();
  if(readiness.requiresOpenAIKey){
    res.status(428).json({
      ok:false,
      code:'openai_connection_required',
      error:'Connect your OpenAI API key before starting VAL.',
      readiness
    });
    return false;
  }
  return true;
}
async function witnessingConnectionStatusPayload(){
  const [google,microsoftTokens]=await Promise.all([
    getGoogleConnectionStatus(GOOGLE_SCOPES).catch(error=>({connected:false,error:error.message,missingScopes:GOOGLE_SCOPES})),
    loadOAuthTokens('microsoft').catch(()=>null)
  ]);
  const openai=await tenantOpenAIConnectionReadiness();
  const krisp=await krispOAuthConnectionStatus().catch(error=>({connected:false,error:error.message||'Krisp needs to reconnect.'}));
  return {
    ok:true,
    source:'witnessing_connection_hub',
    connections:[
      {
        id:'google',
        label:'Google',
        status:google.connected?'connected':'not_connected',
        connected:!!google.connected,
        action:'oauth',
        actionHref:'/auth/google',
        learns:'Gmail, Google Calendar, Drive, and Docs context.',
        limits:'VAL reads evidence only. It never sends, changes a calendar, or shares a file without approval.',
        missingScopes:google.missingScopes||[],
        error:google.error||''
      },
      {
        id:'microsoft',
        label:'Outlook',
        status:microsoftTokens?.refresh_token?'connected':'not_connected',
        connected:!!microsoftTokens?.refresh_token,
        action:'oauth',
        actionHref:'/auth/microsoft',
        learns:'Outlook email and Microsoft Calendar context.',
        limits:'VAL reads evidence only. It never sends, changes a calendar, or shares a file without approval.',
        error:''
      },
      {
        id:'krisp',
        label:'Krisp transcripts',
        configured:!!krisp.connected,
        status:krisp.connected?'connected':'not_connected',
        connected:!!krisp.connected,
        action:'oauth',
        actionHref:'/auth/krisp',
        learns:'Meeting transcripts, exact Action Items, and Key Points from Krisp.',
        limits:'Sign in to let VAL read your Krisp meeting material. VAL keeps the original transcript exactly as Krisp provided it.',
        error:krisp.error||''
      },
      {
        id:'openai',
        label:'OpenAI',
        configured:!!openai.connected,
        status:openai.status||'not_connected',
        connected:!!openai.connected,
        lastUpdatedAt:openai.lastUpdatedAt||'',
        lastTestedAt:openai.lastTestedAt||'',
        action:'credential',
        learns:'Nothing from your world. This powers VAL\'s live reasoning and Witnessing responses.',
        limits:'A saved key is encrypted and never shown again.',
        error:''
      }
    ]
  };
}
