app.post('/api/val/os/rules',async(req,res)=>{
  try{
    const action=String(req.body.action||'approve').toLowerCase();
    const insight=req.body.insight||{};
    const draftId=String(req.body.draftId||valOsDraftKey(insight)||'');
    if(!draftId)return res.status(400).json({ok:false,error:'Missing behavior candidate id.'});
    if(action==='skip'||action==='reject'){
      const decision=saveValOsRuleDecision({draftId,status:'skipped',reason:req.body.reason||'Skipped by user.',insight});
      const audit=saveValOsAudit({eventType:'behavior_skipped',resourceId:draftId,summary:`Skipped behavior candidate: ${insight.title||draftId}`,metadata:{insight}});
      await auditLog({req,action:'val_os_rule_skipped',resourceType:'val_os_rule_draft',resourceId:draftId,metadata:{title:insight.title||''},success:true}).catch(()=>{});
      return res.json({ok:true,status:'skipped',decision,audit,os:await buildValOsState()});
    }
    const ruleDraft=req.body.ruleDraft||insight.data?.ruleDraft||{};
    const rule=saveValOsRule({
      title:req.body.title||insight.title,
      summary:req.body.summary||insight.summary,
      ruleDraft,
      scope:req.body.scope||ruleDraft.scope,
      ruleType:req.body.ruleType||ruleDraft.ruleType,
      confidence:insight.confidence,
      sourceInsightId:draftId,
      executionMode:'review_first',
      approvalRequired:true,
      createdFrom:'my_val_os_approval'
    });
    const decision=saveValOsRuleDecision({draftId,status:'approved',ruleId:rule.id,reason:req.body.reason||'Approved by user in My VAL OS.',insight});
    const audit=saveValOsAudit({eventType:'rule_approved',resourceId:rule.id,summary:`Approved behavior: ${rule.title}`,metadata:{rule,sourceInsightId:draftId}});
    await auditLog({req,action:'val_os_rule_approved',resourceType:'val_os_rule',resourceId:rule.id,metadata:{scope:rule.scope,ruleType:rule.ruleType,sourceInsightId:draftId},success:true}).catch(()=>{});
    res.json({ok:true,status:'approved',rule,decision,audit,os:await buildValOsState()});
  }catch(e){res.status(500).json({ok:false,error:e.message});}
});
app.post('/api/teach-val/onboarding/start',async(req,res)=>{
  try{
    if(!(await requireOpenAIForNewWitnessing(res))) return;
    let existing=null;
    if(req.body.resume===true){
      if(req.body.resumeWitnessing) existing=await getTeachValWitnessingResumeSession();
      existing=existing||await getTeachValSession(req.body.sessionId||'');
    }
    const requestedMode=req.body.mode==='update'?'update':'onboarding';
    const isNew=!existing;
    const session=existing||await saveTeachValSession({id:uuid('tvo'),tenantId:tenantId(),userId:currentUserId(),status:'draft',state:{...teachValDefaultState(),stage:'welcome',mode:requestedMode,testMode:req.body.testMode!==false},createdAt:new Date().toISOString()});
    const state=normalizeTeachValState(session.state);
    state.mode=requestedMode;
    if(isNew){
      state.stage='welcome';
      state.progress.welcome='Ready';
    }
    session.state=state;
    await saveTeachValSession(session);
    res.json(await teachValStateResponse(session.id));
  }catch(e){res.status(500).json({ok:false,error:e.message});}
});
app.post('/api/teach-val/onboarding/:id/reset',async(req,res)=>{
  try{
    if(!(await requireOpenAIForNewWitnessing(res))) return;
    const old=await getTeachValSession(req.params.id);
    if(old){
      old.status='archived';
      old.state=normalizeTeachValState({...old.state,lastError:'Started over '+new Date().toISOString()});
      await saveTeachValSession(old);
    }
    const mode=req.body.mode==='update'?'update':'onboarding';
    const session=await saveTeachValSession({id:uuid('tvo'),tenantId:tenantId(),userId:currentUserId(),status:'draft',state:{...teachValDefaultState(),stage:'welcome',mode,testMode:req.body.testMode!==false},createdAt:new Date().toISOString()});
    res.json(await teachValStateResponse(session.id));
  }catch(e){res.status(500).json({ok:false,error:e.message});}
});
app.post('/api/teach-val/onboarding/:id/voice-turn',async(req,res)=>{
  try{
    const session=await getTeachValSession(req.params.id);
    if(!session)return res.status(404).json({ok:false,error:'Teach VAL onboarding session not found.'});
    const state=normalizeTeachValState(session.state);
    const voice={...state.voiceInterview,turns:Array.isArray(state.voiceInterview.turns)?state.voiceInterview.turns:[]};
    const now=new Date().toISOString();
    const userMessage=String(req.body.message||'').trim();
    if(userMessage)voice.turns.push({role:'user',content:userMessage,createdAt:now});
    let reply='';
    if(req.body.start||!voice.turns.length){
      reply='I am here with you. We will take this slowly. Start with just this: what are you building or carrying right now? You can answer in whatever order feels natural.';
      if(!voice.turns.some(t=>t.role==='assistant'&&t.content===reply))voice.turns.push({role:'assistant',content:reply,createdAt:now});
    }else{
      const recent=voice.turns.slice(-12).map(t=>(t.role==='user'?'Owner':'VAL')+': '+t.content).join('\n\n');
      const system=[
        TEACH_VAL_VOICE_PROMPT,
        'Continue the onboarding interview inside the dashboard.',
        'Reply in under 55 words.',
        'Briefly reflect one thing you heard, then ask exactly one warm follow-up question about one topic only.',
        'If the owner shared a lot, do not ask for a new category yet. First ask a patient clarifying question about the most important thread.',
        'Do not sound like a survey. Do not mention saving or setup unless the user asks.'
      ].join('\n\n');
      reply=await callValModel({system,user:recent,maxTokens:220,temperature:0.38}).catch(()=>'That helps. What part of that feels most important for me to understand first?');
      reply=String(reply||'That helps. What part of that feels most important for me to understand first?').trim();
      voice.turns.push({role:'assistant',content:reply,createdAt:now});
    }
    voice.transcript=voice.turns.map(t=>(t.role==='user'?'You':'VAL')+': '+t.content).join('\n\n');
    voice.status='In Progress';
    state.voiceInterview=voice;
    state.stage='voice_interview';
    state.progress.voice_interview='In Progress';
    session.state=state;
    await saveTeachValSession(session);
    res.json({...await teachValStateResponse(session.id),reply});
  }catch(e){res.status(500).json({ok:false,error:e.message});}
});
