app.post('/api/val/first-look/prepare',async(req,res)=>{
  res.status(200);
  res.set({
    'Content-Type':'application/x-ndjson; charset=utf-8',
    'Cache-Control':'no-store, no-cache, must-revalidate',
    'X-Accel-Buffering':'no'
  });
  res.flushHeaders?.();
  const write=(event={})=>{
    if(!res.writableEnded){
      res.write(JSON.stringify(event)+'\n');
      res.flush?.();
    }
  };
  try{
    const sessionId=String(req.body?.sessionId||'').trim();
    if(!sessionId) throw new Error('The Witnessing Session is not ready yet. Return to the session and try again.');
    const session=await getTeachValSession(sessionId);
    if(!session) throw new Error('This Witnessing Session could not be found. Start the session again before preparing the First Look.');
    await setCleanStartSourceIntakeLocked(false);
    const existing=await getValFirstLookRun();
    if(existing?.status==='complete'){
      write({type:'progress',source:'snapshot',state:'complete',message:'Opening your existing First Look. VAL does not regenerate it.'});
      write({type:'complete',run:existing,reused:true});
      return res.end();
    }
    write({type:'progress',source:'snapshot',state:'reading',message:'Starting your private, review-only First Look.'});
    const snapshot=await buildValFirstLookSnapshot({
      scope:String(req.body?.scope||'').trim(),
      onProgress:write
    });
    write({type:'progress',source:'snapshot',state:'saving',message:'Saving this exact First Look receipt. Nothing else is being created.'});
    const run=await saveValFirstLookRun({
      sessionId:session.id,
      status:'complete',
      windowStart:snapshot.window.start,
      windowEnd:snapshot.window.end,
      scope:snapshot.scope,
      snapshot,
      completedAt:snapshot.completedAt
    });
    write({type:'complete',run,reused:false});
  }catch(error){
    write({type:'error',message:firstLookError(error)});
  }
  res.end();
});
app.post('/api/teach-val/onboarding/:id/commit',async(req,res)=>{
  try{
    const session=await getTeachValSession(req.params.id);
    if(!session)return res.status(404).json({ok:false,error:'Teach VAL onboarding session not found.'});
    const imports=await listTeachValImports(session.id);
    const included=imports.flatMap(i=>(i.extractedItems||[]).filter(item=>item.include_in_val!==false).map(item=>({
      sessionId:session.id,
      category:item.category||i.category,
      title:item.title||item.name||i.category,
      summary:item.summary||'',
      source:item.source||'teach_val_onboarding',
      confidence:Number(item.confidence||0.72),
      data:{...item.data,itemId:item.id,importId:i.id,sourceCategory:i.category}
    })));
    const testMode=req.body.testMode!==undefined?!!req.body.testMode:!!session.state.testMode;
    const payload=teachValCompiledPayload({session,imports,items:included,testMode});
    const operationalInsights=teachValOnboardingOperationalInsights({session,items:included});
    const state=normalizeTeachValState(session.state);
    let webhook={status:testMode?'test_mode':'not_configured',message:testMode?'Test mode: payload built but not sent to production memory.':'No external onboarding webhook configured. Stored in local VAL onboarding memory.'};
    let promotion={memoryCount:0,evidenceItemId:'',observationCount:0,intelligence:null};
    if(!testMode){
      await insertTeachValMemoryItems(included);
      if(operationalInsights.length){
        const existingOperational=(await listTeachValImports(session.id)).find(i=>i.category==='onboarding_operational_context');
        await saveTeachValImport({
          id:existingOperational?.id,
          sessionId:session.id,
          category:'onboarding_operational_context',
          promptUsed:'Operationalize Teach VAL onboarding into reviewable VAL OS behavior candidates, support-circle context, and document-reference learning.',
          rawResponse:JSON.stringify({source:'teach_val_onboarding',sessionId:session.id,itemCount:operationalInsights.length},null,2),
          structuredSummary:{
            source:'teach_val_onboarding',
            behaviorCandidates:operationalInsights.filter(i=>i.data?.ruleDraft).length,
            learningItems:operationalInsights.filter(i=>!i.data?.ruleDraft).length,
            externalActionTaken:false,
            reviewRequired:true
          },
          extractedItems:operationalInsights,
          reviewed:false,
          status:'Ready for VAL OS Review'
        });
      }
      promotion=await promoteTeachValOnboardingToCoreMemory({session,imports,items:included,payload});
      const url=process.env.TEACH_VAL_WEBHOOK_URL||process.env.VAL_ONBOARDING_WEBHOOK_URL||'';
      if(url){
        try{
          const r=await fetch(url,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(payload)});
          const body=await readJsonResponse(r).catch(()=>({}));
          webhook={status:r.ok?'sent':'failed',statusCode:r.status,message:r.ok?'Webhook sent successfully.':(body.error||body.message||`Webhook failed with status ${r.status}`)};
          if(!r.ok) throw new Error(webhook.message);
        }catch(e){
          webhook={status:'failed',message:e.message};
          state.lastError='Webhook failed: '+e.message;
          state.webhookAttempts=(state.webhookAttempts||[]).concat({at:new Date().toISOString(),status:'failed',message:e.message});
          session.state=state;await saveTeachValSession(session);
          return res.status(502).json({ok:false,error:'Teach VAL could not send the onboarding webhook. '+e.message,payload,webhook});
        }
      }
    }
    state.stage='complete';
    state.progress.review='Reviewed';
    state.progress.send_to_val=testMode?'Tested':'Sent to VAL';
    state.webhookAttempts=(state.webhookAttempts||[]).concat({at:new Date().toISOString(),...webhook});
    session.status=testMode?'test_completed':'committed';
    session.state=state;
    await saveTeachValSession(session);
    await auditLog({req,action:testMode?'teach_val_onboarding_tested':'teach_val_onboarding_committed',resourceType:'teach_val_onboarding',resourceId:session.id,metadata:{itemCount:included.length,webhook:webhook.status,promotion,operationalInsightCount:operationalInsights.length},success:webhook.status!=='failed'}).catch(()=>{});
    res.json({ok:true,payload,webhook,promotion,operationalInsights:testMode?operationalInsights:operationalInsights.map(i=>({id:i.id,title:i.title,category:i.data?.sourceCategory,hasRuleDraft:!!i.data?.ruleDraft,targetRooms:i.data?.targetRooms||[]})),memory:testMode?[]:await listTeachValMemory(session.id),state});
  }catch(e){res.status(500).json({ok:false,error:e.message});}
});
