// GOOGLE OAUTH
// ════════════════════════════════════════════════════════

function firstEnvValue(names){
  for(const name of names){
    const value=String(process.env[name]||'').trim();
    if(value) return value;
  }
  return '';
}
const GOOGLE_CLIENT_ID_ENV_NAMES = ['GOOGLE_CLIENT_ID','GOOGLE_OAUTH_CLIENT_ID','GOOGLE_AUTH_CLIENT_ID'];
const GOOGLE_CLIENT_SECRET_ENV_NAMES = ['GOOGLE_CLIENT_SECRET','GOOGLE_OAUTH_CLIENT_SECRET','GOOGLE_AUTH_CLIENT_SECRET'];
const GOOGLE_REDIRECT_URI_ENV_NAMES = ['GOOGLE_REDIRECT_URI','GOOGLE_OAUTH_REDIRECT_URI','REDIRECT_URI'];
const GOOGLE_CLIENT_ID     = firstEnvValue(GOOGLE_CLIENT_ID_ENV_NAMES);
const GOOGLE_CLIENT_SECRET = firstEnvValue(GOOGLE_CLIENT_SECRET_ENV_NAMES);
const CONFIGURED_GOOGLE_REDIRECT_URI = firstEnvValue(GOOGLE_REDIRECT_URI_ENV_NAMES);
const REDIRECT_URI         = CONFIGURED_GOOGLE_REDIRECT_URI || `${CLIENT_CONFIG.publicBaseUrl}/auth/callback`;
const DEFAULT_GOOGLE_SCOPES = [
  'https://www.googleapis.com/auth/calendar.readonly',
  'https://www.googleapis.com/auth/calendar.events',
  'https://www.googleapis.com/auth/gmail.readonly',
  'https://www.googleapis.com/auth/gmail.compose',
  'https://www.googleapis.com/auth/drive.readonly',
  'https://www.googleapis.com/auth/drive.file',
  'https://www.googleapis.com/auth/documents'
];
const GOOGLE_SCOPES = String(process.env.GOOGLE_SCOPES||'').trim()
  ? Array.from(new Set(String(process.env.GOOGLE_SCOPES).split(/\s+/).map(s=>s.trim()).filter(Boolean).concat([
      'https://www.googleapis.com/auth/drive.readonly',
      'https://www.googleapis.com/auth/drive.file',
      'https://www.googleapis.com/auth/documents',
      'https://www.googleapis.com/auth/calendar.events'
    ])))
  : DEFAULT_GOOGLE_SCOPES;
const REQUIRED_GMAIL_SCOPES = [
  'https://www.googleapis.com/auth/gmail.readonly',
  'https://www.googleapis.com/auth/gmail.compose'
];
const REQUIRED_GOOGLE_DOC_SCOPES = [
  'https://www.googleapis.com/auth/drive.readonly',
  'https://www.googleapis.com/auth/drive.file',
  'https://www.googleapis.com/auth/documents'
];
let googleTokens = {}; // hot cache; durable copy lives in Postgres scoped by tenant/user.
let googleTokensLoaded = false;
let lastGoogleAuthError = null;
let gmailSyncStatus = {lastAttemptAt:'',lastSuccessfulSyncAt:'',lastError:'',lastFetchedCount:0,lastAnalyzedCount:0,lastQuery:''};

function validGoogleClientId(id=GOOGLE_CLIENT_ID){
  return /^\d+[-\w]*\.apps\.googleusercontent\.com$/.test(String(id||'').trim());
}
function googleRedirectUri(req=null){
  return CONFIGURED_GOOGLE_REDIRECT_URI || (req ? `${requestBaseUrl(req)}/auth/callback` : REDIRECT_URI);
}
function googleOAuthConfigProblems(req=null){
  const problems=[];
  if(!GOOGLE_CLIENT_ID) problems.push(`Missing ${GOOGLE_CLIENT_ID_ENV_NAMES.join(' or ')}`);
  else if(!validGoogleClientId()) problems.push('GOOGLE_CLIENT_ID does not look like a Google OAuth web client ID ending in .apps.googleusercontent.com');
  if(!GOOGLE_CLIENT_SECRET) problems.push(`Missing ${GOOGLE_CLIENT_SECRET_ENV_NAMES.join(' or ')}`);
  if(!googleRedirectUri(req)) problems.push(`Missing ${GOOGLE_REDIRECT_URI_ENV_NAMES.join(' or ')} or VAL_PUBLIC_BASE_URL`);
  if(IS_PRODUCTION&&!encryptionConfigured()) problems.push('Missing ENCRYPTION_KEY in this Railway service/environment; production OAuth token saves are blocked until it is available at runtime');
  return problems;
}
function googleOAuthConfigSnapshot(){
  return {
    ok:googleOAuthConfigProblems().length===0,
    clientIdConfigured:!!GOOGLE_CLIENT_ID,
    clientIdLooksValid:validGoogleClientId(),
    clientId:maskSecret(GOOGLE_CLIENT_ID),
    clientSecretConfigured:!!GOOGLE_CLIENT_SECRET,
    redirectUri:googleRedirectUri(),
    encryptionConfigured:encryptionConfigured(),
    envNames:{
      clientId:GOOGLE_CLIENT_ID_ENV_NAMES,
      clientSecret:GOOGLE_CLIENT_SECRET_ENV_NAMES,
      redirectUri:GOOGLE_REDIRECT_URI_ENV_NAMES,
      encryptionKey:'ENCRYPTION_KEY'
    },
    problems:googleOAuthConfigProblems()
  };
}

// Optional legacy fallback only. Prefer OAuth reconnect so tokens are scoped to this VAL tenant/user.
if(process.env.GOOGLE_REFRESH_TOKEN && /^(1|true|yes)$/i.test(String(process.env.ALLOW_GOOGLE_REFRESH_TOKEN_ENV||''))){
  googleTokens.refresh_token = process.env.GOOGLE_REFRESH_TOKEN;
  googleTokens.issued_at = 0; // force refresh on first use
  console.log('Loaded Google refresh token from env var because ALLOW_GOOGLE_REFRESH_TOKEN_ENV is enabled');
}

async function saveOAuthTokens(provider,tokens){
  if(!tokens||!Object.keys(tokens).length) return;
  const userId=currentUserId();
  const tenant=tenantId();
  const scopedTokens=encryptOAuthTokens({...tokens,user_id:userId,tenant_id:tenant,client_slug:CLIENT_CONFIG.clientSlug});
  if(pgPool){
    await valDbReady;
    await dbQuery(`
      insert into val_oauth_tokens (provider,user_id,tenant_id,client_slug,tokens,updated_at)
      values ($1,$2,$3,$4,$5,now())
      on conflict (tenant_id,user_id,provider)
      do update set client_slug=excluded.client_slug,tokens=excluded.tokens,updated_at=now()
    `,[provider,userId,tenant,CLIENT_CONFIG.clientSlug,JSON.stringify(scopedTokens)]);
  }else{
    const store=valStore();
    store.oauthTokens=store.oauthTokens||{};
    store.oauthTokens[`${tenant}:${userId}:${provider}`]=scopedTokens;
    saveValStore(store);
  }
}

async function loadOAuthTokens(provider){
  await valDbReady;
  const userId=currentUserId();
  const tenant=tenantId();
  if(pgPool){
    const r=await dbQuery('select tokens from val_oauth_tokens where provider=$1 and tenant_id=$2 and user_id=$3 order by updated_at desc limit 1',[provider,tenant,userId]);
    return r.rows[0]?.tokens ? decryptOAuthTokens(r.rows[0].tokens) : null;
  }
  const tokens=valStore().oauthTokens||{};
  return tokens[`${tenant}:${userId}:${provider}`] ? decryptOAuthTokens(tokens[`${tenant}:${userId}:${provider}`]) : null;
}

const KRISP_OAUTH_CLIENT_ID_ENV_NAMES = ['KRISP_OAUTH_CLIENT_ID','KRISP_CLIENT_ID'];
const KRISP_OAUTH_CLIENT_SECRET_ENV_NAMES = ['KRISP_OAUTH_CLIENT_SECRET','KRISP_CLIENT_SECRET'];
const KRISP_OAUTH_REDIRECT_URI_ENV_NAMES = ['KRISP_OAUTH_REDIRECT_URI','KRISP_REDIRECT_URI'];
const KRISP_OAUTH_CLIENT_ID = firstEnvValue(KRISP_OAUTH_CLIENT_ID_ENV_NAMES);
const KRISP_OAUTH_CLIENT_SECRET = firstEnvValue(KRISP_OAUTH_CLIENT_SECRET_ENV_NAMES);
const CONFIGURED_KRISP_OAUTH_REDIRECT_URI = firstEnvValue(KRISP_OAUTH_REDIRECT_URI_ENV_NAMES);
const KRISP_OAUTH_SCOPES = [
  'user::me::read',
  'user::meetings::list',
  'user::meetings:metadata::read',
  'user::meetings:notes::read',
  'user::meetings:transcripts::read'
];
const CONFIGURED_KRISP_OAUTH_METADATA = KRISP_OAUTH_CLIENT_ID ? {
  resource:'https://mcp.krisp.ai',
  authorizationServer:'https://mcp.krisp.ai',
  authorizationEndpoint:'https://api.krisp.ai/platform/v1/oauth2/authorize',
  tokenEndpoint:'https://api.krisp.ai/platform/v1/oauth2/token',
  registrationEndpoint:'',
  scopesSupported:KRISP_OAUTH_SCOPES,
  tokenEndpointAuthMethods:['client_secret_basic','client_secret_post']
} : null;
const KRISP_OAUTH_PENDING_TTL_MS = 10 * 60 * 1000;
const krispOAuthPendingAuthorizations = new Map();
let krispOAuthMetadataCache = {value:null,expiresAt:0};

function krispOAuthRedirectUri(req=null){
  return CONFIGURED_KRISP_OAUTH_REDIRECT_URI || (req ? `${requestBaseUrl(req)}/auth/krisp/callback` : `${CLIENT_CONFIG.publicBaseUrl}/auth/krisp/callback`);
}

function base64urlSha256(value=''){
  return crypto.createHash('sha256').update(String(value)).digest('base64url');
}

function cleanExpiredKrispOAuthAuthorizations(){
  const expiresBefore=Date.now()-KRISP_OAUTH_PENDING_TTL_MS;
  for(const [state,entry] of krispOAuthPendingAuthorizations){
    if(Number(entry?.createdAt||0)<expiresBefore) krispOAuthPendingAuthorizations.delete(state);
  }
}

async function fetchKrispOAuthJson(url,options={}){
  const response=await fetch(url,{headers:{Accept:'application/json',...(options.headers||{})},...options});
  const body=await readJsonResponse(response);
  if(!response.ok||body?.error) throw new Error(body?.error_description||body?.error||body?.message||`Krisp OAuth request failed (${response.status})`);
  return body;
}

async function discoverKrispOAuthMetadata({force=false}={}){
  if(!force&&krispOAuthMetadataCache.value&&Date.now()<krispOAuthMetadataCache.expiresAt) return krispOAuthMetadataCache.value;
  const mcpUrl=new URL(KRISP_MCP_URL);
  const discoveryUrls=Array.from(new Set([
    `${KRISP_MCP_URL.replace(/\/+$/,'')}/.well-known/oauth-protected-resource`,
    `${mcpUrl.origin}/.well-known/oauth-protected-resource`
  ]));
  let resourceMetadata=null;
  let discoveryError=null;
  for(const url of discoveryUrls){
    try{
      const candidate=await fetchKrispOAuthJson(url);
      if(Array.isArray(candidate?.authorization_servers)&&candidate.authorization_servers.length){
        resourceMetadata=candidate;
        break;
      }
    }catch(error){
      discoveryError=error;
    }
  }
  if(!resourceMetadata) throw new Error(discoveryError?.message||'Krisp OAuth discovery is unavailable right now.');
  const authorizationServer=String(resourceMetadata.authorization_servers[0]||'').replace(/\/+$/,'');
  const authorizationMetadata=await fetchKrispOAuthJson(`${authorizationServer}/.well-known/oauth-authorization-server`);
  if(!authorizationMetadata.authorization_endpoint||!authorizationMetadata.token_endpoint){
    throw new Error('Krisp OAuth did not provide the connection details VAL needs.');
  }
  const metadata={
    resource:resourceMetadata.resource||mcpUrl.origin,
    authorizationServer,
    authorizationEndpoint:authorizationMetadata.authorization_endpoint,
    tokenEndpoint:authorizationMetadata.token_endpoint,
    registrationEndpoint:authorizationMetadata.registration_endpoint||'',
    scopesSupported:Array.isArray(authorizationMetadata.scopes_supported)?authorizationMetadata.scopes_supported:[],
    tokenEndpointAuthMethods:Array.isArray(authorizationMetadata.token_endpoint_auth_methods_supported)?authorizationMetadata.token_endpoint_auth_methods_supported:[]
  };
  krispOAuthMetadataCache={value:metadata,expiresAt:Date.now()+5*60*1000};
  return metadata;
}

async function registerKrispOAuthClient(metadata,redirectUri){
  if(!metadata.registrationEndpoint) throw new Error('Krisp did not provide a secure registration route for this connection.');
  const response=await fetch(metadata.registrationEndpoint,{
    method:'POST',
    headers:{Accept:'application/json','Content-Type':'application/json'},
    body:JSON.stringify({
      client_name:'VAL',
      redirect_uris:[redirectUri],
      response_types:['code'],
      grant_types:['authorization_code','refresh_token'],
      token_endpoint_auth_method:metadata.tokenEndpointAuthMethods.includes('client_secret_post')?'client_secret_post':'client_secret_basic'
    })
  });
  const registration=await readJsonResponse(response);
  if(!response.ok||!registration?.client_id){
    throw new Error(registration?.error_description||registration?.error||registration?.message||'Krisp could not prepare the secure connection.');
  }
  return {clientId:registration.client_id,clientSecret:registration.client_secret||'',tokenAuthMethod:registration.token_endpoint_auth_method||'client_secret_post'};
}

async function krispOAuthClientForConnection(metadata,redirectUri){
  if(KRISP_OAUTH_CLIENT_ID){
    return {clientId:KRISP_OAUTH_CLIENT_ID,clientSecret:KRISP_OAUTH_CLIENT_SECRET,tokenAuthMethod:'client_secret_post'};
  }
  const saved=await loadOAuthTokens('krisp').catch(()=>null);
  if(saved?.oauth_client_id){
    return {clientId:saved.oauth_client_id,clientSecret:saved.oauth_client_secret||'',tokenAuthMethod:saved.oauth_token_auth_method||'client_secret_post'};
  }
  const registered=await registerKrispOAuthClient(metadata,redirectUri);
  // Dynamic registration can be slow. Persist the client before the user
  // signs in so returning to the connection does not repeat that wait.
  await saveOAuthTokens('krisp',{
    oauth_client_id:registered.clientId,
    oauth_client_secret:registered.clientSecret,
    oauth_token_auth_method:registered.tokenAuthMethod
  });
  return registered;
}

function krispTokenExpiresAt(tokens={}){
  if(!tokens?.issued_at||!tokens?.expires_in) return 0;
  return Number(tokens.issued_at)+(Number(tokens.expires_in)*1000)-60000;
}

async function getKrispOAuthAccessToken(){
  const saved=await loadOAuthTokens('krisp').catch(()=>null);
  if(!saved?.access_token) return '';
  const expiresAt=krispTokenExpiresAt(saved);
  if(!expiresAt||Date.now()<expiresAt) return saved.access_token;
  if(!saved.refresh_token||!saved.oauth_token_endpoint||!saved.oauth_client_id) return '';
  const form=new URLSearchParams({
    grant_type:'refresh_token',
    refresh_token:saved.refresh_token,
    client_id:saved.oauth_client_id
  });
  if(saved.oauth_client_secret) form.set('client_secret',saved.oauth_client_secret);
  try{
    const refreshed=await fetchKrispOAuthJson(saved.oauth_token_endpoint,{
      method:'POST',
      headers:{'Content-Type':'application/x-www-form-urlencoded'},
      body:form.toString()
    });
    const next={...saved,...refreshed,refresh_token:refreshed.refresh_token||saved.refresh_token,issued_at:Date.now()};
    await saveOAuthTokens('krisp',next);
    return next.access_token||'';
  }catch(error){
    console.error('Krisp token refresh failed:',error.message);
    return '';
  }
}

async function krispOAuthConnectionStatus(){
  const saved=await loadOAuthTokens('krisp').catch(()=>null);
  if(saved?.access_token){
    const accessToken=await getKrispOAuthAccessToken();
    return {
      connected:!!accessToken,
      source:'oauth',
      scopes:String(saved.scope||'').split(/\s+/).filter(Boolean),
      error:accessToken?'':'Krisp needs to reconnect.'
    };
  }
  const legacyToken=await resolveIntegrationSecret('krisp','access_token',KRISP_MCP_ACCESS_TOKEN).catch(()=>KRISP_MCP_ACCESS_TOKEN);
  return {connected:!!legacyToken,source:legacyToken?'service_credential':'none',scopes:[],error:''};
}

async function resolveKrispAccessToken(fallback=''){
  const saved=await loadOAuthTokens('krisp').catch(()=>null);
  if(saved?.access_token) return getKrispOAuthAccessToken().catch(()=> '');
  const credential=await resolveIntegrationSecret('krisp','access_token',fallback||KRISP_MCP_ACCESS_TOKEN).catch(()=>fallback||KRISP_MCP_ACCESS_TOKEN);
  return credential || resolveIntegrationSecret('krisp','api_key',fallback||KRISP_MCP_ACCESS_TOKEN);
}

async function ensureGoogleTokensLoaded(){
  if(googleTokensLoaded) return;
  const saved=await loadOAuthTokens('google');
  if(saved){
    googleTokens={...googleTokens,...saved};
    console.log('Loaded Google tokens from VAL store');
  }
  googleTokensLoaded = true;
}

function googleScopeList(tokens=googleTokens){
  return String(tokens?.scope||'').split(/\s+/).map(s=>s.trim()).filter(Boolean);
}
function missingGoogleScopes(required=GOOGLE_SCOPES,tokens=googleTokens){
  const scopes=new Set(googleScopeList(tokens));
  return required.filter(scope=>!scopes.has(scope));
}
function googleTokenExpiresAt(tokens=googleTokens){
  if(!tokens?.issued_at||!tokens?.expires_in) return '';
  return new Date(Number(tokens.issued_at)+Number(tokens.expires_in)*1000).toISOString();
}
async function hydrateGoogleTokenScopes(accessToken){
  if(!accessToken) return googleScopeList();
  try{
    const r=await fetch(`https://oauth2.googleapis.com/tokeninfo?access_token=${encodeURIComponent(accessToken)}`);
    const d=await readJsonResponse(r);
    if(r.ok&&d.scope){
      const nextScope=String(d.scope||'').trim();
      if(nextScope&&nextScope!==googleTokens.scope){
        googleTokens={...googleTokens,scope:nextScope};
        await saveOAuthTokens('google',googleTokens);
      }
      return googleScopeList();
    }
  }catch(e){}
  return googleScopeList();
}
async function getGoogleConnectionStatus(requiredScopes=GOOGLE_SCOPES){
  await ensureGoogleTokensLoaded();
  const hasRefreshToken=!!googleTokens.refresh_token;
  const token=await getGoogleToken();
  if(token) await hydrateGoogleTokenScopes(token);
  const scopes=googleScopeList();
  const missingScopes=missingGoogleScopes(requiredScopes);
  return {
    connected:!!token&&missingScopes.length===0,
    hasAccessToken:!!token,
    hasRefreshToken,
    scopes,
    missingScopes,
    tokenExpiresAt:googleTokenExpiresAt(),
    error:token ? (missingScopes.length?'Reconnect required for missing Google scopes.':'') : (lastGoogleAuthError||'Google auth required')
  };
}

