app.get('/auth/krisp/start',async(req,res)=>{
  try{
    cleanExpiredKrispOAuthAuthorizations();
    const redirectUri=krispOAuthRedirectUri(req);
    const metadata=CONFIGURED_KRISP_OAUTH_METADATA||await discoverKrispOAuthMetadata();
    const client=await krispOAuthClientForConnection(metadata,redirectUri);
    const verifier=crypto.randomBytes(32).toString('base64url');
    const state=crypto.randomBytes(32).toString('base64url');
    const requestedScopes=KRISP_OAUTH_SCOPES.filter(scope=>!metadata.scopesSupported.length||metadata.scopesSupported.includes(scope));
    krispOAuthPendingAuthorizations.set(state,{
      createdAt:Date.now(),
      verifier,
      redirectUri,
      resource:metadata.resource,
      tokenEndpoint:metadata.tokenEndpoint,
      clientId:client.clientId,
      clientSecret:client.clientSecret,
      tokenAuthMethod:client.tokenAuthMethod
    });
    const authorizationUrl=new URL(metadata.authorizationEndpoint);
    authorizationUrl.search=new URLSearchParams({
      response_type:'code',
      client_id:client.clientId,
      redirect_uri:redirectUri,
      scope:requestedScopes.join(' '),
      state,
      code_challenge:base64urlSha256(verifier),
      code_challenge_method:'S256',
      resource:metadata.resource
    }).toString();
    res.redirect(authorizationUrl.toString());
  }catch(error){
    console.error('Krisp OAuth start failed:',error.message);
    res.status(500).send(`<!doctype html><html><head><meta charset="utf-8"><title>Krisp cannot connect to VAL</title></head><body style="font-family:sans-serif;padding:2rem"><h2>Krisp cannot connect to VAL yet.</h2><p>${escapeHtml(error.message||'Please try again in a moment.')}</p><p>Close this window and try Connect Krisp again.</p></body></html>`);
  }
});

app.get('/auth/krisp/callback',async(req,res)=>{
  const code=String(req.query.code||'');
  const state=String(req.query.state||'');
  const providerError=String(req.query.error||'');
  cleanExpiredKrispOAuthAuthorizations();
  const pending=krispOAuthPendingAuthorizations.get(state);
  krispOAuthPendingAuthorizations.delete(state);
  if(providerError) return res.status(400).send(`<!doctype html><html><body style="font-family:sans-serif;padding:2rem"><h2>Krisp connection was not completed.</h2><p>${escapeHtml(String(req.query.error_description||providerError))}</p></body></html>`);
  if(!code||!state||!pending) return res.status(400).send('<!doctype html><html><body style="font-family:sans-serif;padding:2rem"><h2>Krisp connection expired.</h2><p>Close this window and start Connect Krisp again from VAL.</p></body></html>');
  try{
    const form=new URLSearchParams({
      grant_type:'authorization_code',
      code,
      redirect_uri:pending.redirectUri,
      client_id:pending.clientId,
      code_verifier:pending.verifier
    });
    if(pending.clientSecret) form.set('client_secret',pending.clientSecret);
    const tokens=await fetchKrispOAuthJson(pending.tokenEndpoint,{
      method:'POST',
      headers:{'Content-Type':'application/x-www-form-urlencoded'},
      body:form.toString()
    });
    if(!tokens.access_token) throw new Error('Krisp did not return an access token.');
    await saveOAuthTokens('krisp',{
      ...tokens,
      issued_at:Date.now(),
      oauth_resource:pending.resource,
      oauth_token_endpoint:pending.tokenEndpoint,
      oauth_client_id:pending.clientId,
      oauth_client_secret:pending.clientSecret,
      oauth_token_auth_method:pending.tokenAuthMethod
    });
    await auditLog({req,action:'oauth_account_connected',resourceType:'oauth',resourceId:'krisp',metadata:{scopes:String(tokens.scope||KRISP_OAUTH_SCOPES.join(' ')).split(/\s+/),hasRefreshToken:!!tokens.refresh_token},success:true}).catch(()=>{});
    res.send(`<!doctype html><html><head><meta charset="utf-8"><title>Krisp connected to VAL</title></head><body style="font-family:sans-serif;padding:2rem"><h2>Krisp transcripts are connected to VAL.</h2><p>Returning to VAL now.</p><script>if(window.opener){window.opener.postMessage({type:'val-oauth-connected',provider:'krisp'},window.location.origin);window.setTimeout(function(){window.close();},750);}</script></body></html>`);
  }catch(error){
    console.error('Krisp OAuth callback failed:',error.message);
    res.status(500).send(`<!doctype html><html><body style="font-family:sans-serif;padding:2rem"><h2>Krisp could not finish connecting.</h2><p>${escapeHtml(error.message||'Please try again.')}</p><p>Close this window and try Connect Krisp again.</p></body></html>`);
  }
});

// Step 2 — Google redirects back with code, exchange for tokens
app.get('/auth/callback', async (req, res) => {
  const {code} = req.query;
  if(!code) return res.status(400).send('No code received');
  try {
    const problems=googleOAuthConfigProblems(req);
    if(problems.length) throw new Error(problems.join('; '));
    const redirectUri=googleRedirectUri(req);
    const existingTokens = await loadOAuthTokens('google') || googleTokens || {};
    const r = await fetch('https://oauth2.googleapis.com/token', {
      method: 'POST',
      headers: {'Content-Type':'application/x-www-form-urlencoded'},
      body: new URLSearchParams({
        code, client_id: GOOGLE_CLIENT_ID,
        client_secret: GOOGLE_CLIENT_SECRET,
        redirect_uri: redirectUri,
        grant_type: 'authorization_code'
      })
    });
    const exchangedTokens = await r.json();
    if(exchangedTokens.error) throw new Error(exchangedTokens.error_description || exchangedTokens.error);
    googleTokens = {
      ...existingTokens,
      ...exchangedTokens,
      refresh_token: exchangedTokens.refresh_token || existingTokens.refresh_token || process.env.GOOGLE_REFRESH_TOKEN
    };
    googleTokens.issued_at = Date.now();
    googleTokensLoaded = true;
    lastGoogleAuthError = null;
    await saveOAuthTokens('google',googleTokens);
    console.log('Google tokens stored. refresh_token present:', !!googleTokens.refresh_token, 'scope count:', googleScopeList().length);
    await auditLog({req,action:'oauth_account_connected',resourceType:'oauth',resourceId:'google',metadata:{scopes:googleScopeList(),hasRefreshToken:!!googleTokens.refresh_token},success:true}).catch(()=>{});
    res.send(`<!doctype html><html><head><meta charset="utf-8"><title>Google connected to VAL</title></head><body style="font-family:sans-serif;padding:2rem"><h2>Google Calendar, Gmail, Drive, and Docs are connected to VAL.</h2><p>Returning to VAL now.</p><p><a href="/">Return to VAL</a></p><script>if(window.opener){window.opener.postMessage({type:'val-oauth-connected',provider:'google'},window.location.origin);window.setTimeout(function(){window.close();},750);}</script></body></html>`);
  } catch(e) {
    res.status(500).send('Auth failed: '+e.message);
  }
});

// Refresh access token if expired
async function getGoogleToken() {
  await ensureGoogleTokensLoaded();
  // If no access token but we have a refresh token, go get one
  if(!googleTokens.access_token && googleTokens.refresh_token) {
    try {
      const r = await fetch('https://oauth2.googleapis.com/token', {
        method: 'POST',
        headers: {'Content-Type':'application/x-www-form-urlencoded'},
        body: new URLSearchParams({
          client_id: GOOGLE_CLIENT_ID,
          client_secret: GOOGLE_CLIENT_SECRET,
          refresh_token: googleTokens.refresh_token,
          grant_type: 'refresh_token'
        })
      });
      const fresh = await r.json();
      if(fresh.error){ lastGoogleAuthError = fresh.error_description || fresh.error; console.error('Token bootstrap failed:', fresh.error, fresh.error_description); return null; }
      googleTokens = {...googleTokens, ...fresh, issued_at: Date.now()};
      googleTokensLoaded = true;
      lastGoogleAuthError = null;
      await saveOAuthTokens('google',googleTokens);
      await hydrateGoogleTokenScopes(googleTokens.access_token);
      console.log('Bootstrapped access token from refresh token');
      return googleTokens.access_token;
    } catch(e) {
      console.error('Token bootstrap error:', e);
      return null;
    }
  }
  if(!googleTokens.access_token) return null;
  // Check if expired (with 60s buffer)
  const expiresAt = (googleTokens.issued_at||0) + (googleTokens.expires_in||3600)*1000 - 60000;
  if(Date.now() < expiresAt) return googleTokens.access_token;
  if(!googleTokens.refresh_token){
    lastGoogleAuthError='Google refresh token missing. Reconnect required.';
    return null;
  }
  // Refresh
  try {
    const r = await fetch('https://oauth2.googleapis.com/token', {
      method: 'POST',
      headers: {'Content-Type':'application/x-www-form-urlencoded'},
      body: new URLSearchParams({
        client_id: GOOGLE_CLIENT_ID,
        client_secret: GOOGLE_CLIENT_SECRET,
        refresh_token: googleTokens.refresh_token,
        grant_type: 'refresh_token'
      })
    });
    const fresh = await r.json();
    if(fresh.error){
      lastGoogleAuthError = fresh.error_description || fresh.error;
      console.error('Google token refresh failed:', fresh.error);
      if(fresh.error==='invalid_grant') googleTokens.access_token='';
      return null;
    }
    googleTokens = {...googleTokens, ...fresh, issued_at: Date.now()};
    googleTokensLoaded = true;
    lastGoogleAuthError = null;
    await saveOAuthTokens('google',googleTokens);
    await hydrateGoogleTokenScopes(googleTokens.access_token);
    return googleTokens.access_token;
  } catch(e) {
    lastGoogleAuthError = e.message;
    console.error('Token refresh failed:', e);
    return null;
  }
}

async function gmailFetchJson(url,options={},label='Gmail request'){
  let token=await getGoogleToken();
  if(!token) throw new Error(lastGoogleAuthError||'Google auth required');
  let response=await fetch(url,{...options,headers:{...(options.headers||{}),Authorization:`Bearer ${token}`}});
  let data=await readJsonResponse(response);
  if(response.status===401&&googleTokens.refresh_token){
    lastGoogleAuthError='Google access token expired or was rejected. Refreshing token and retrying Gmail.';
    googleTokens={...googleTokens,access_token:'',issued_at:0};
    await saveOAuthTokens('google',googleTokens).catch(()=>{});
    token=await getGoogleToken();
    if(token){
      response=await fetch(url,{...options,headers:{...(options.headers||{}),Authorization:`Bearer ${token}`}});
      data=await readJsonResponse(response);
    }
  }
  if(!response.ok){
    const message=data?.error?.message||`${label} failed (${response.status})`;
    if(response.status===401) lastGoogleAuthError=message;
    throw new Error(message);
  }
  return data;
}

// Auth status check
app.get('/auth/status', async (req, res) => {
  const status=await getGoogleConnectionStatus(GOOGLE_SCOPES);
  res.json({
    connected: status.connected,
    hasRefreshToken: status.hasRefreshToken,
    scopes: status.scopes,
    missingScopes: status.missingScopes,
    tokenExpiresAt: status.tokenExpiresAt,
    needsAuth: !status.connected,
    error: status.error || null
  });
});

