function personKey(name,email){
  const e=String(email||'').trim().toLowerCase();
  if(e) return 'email:'+e;
  return 'name:'+String(name||'Unknown').trim().toLowerCase().replace(/\s+/g,' ');
}
function cleanPersonName(value,email=''){
  const text=String(value||'').replace(/<.*?>/g,'').replace(/["']/g,'').trim();
  if(text&&text.includes('@')) return email ? email.split('@')[0] : text.split('@')[0];
  return collapseRepeatedName(text) || (email ? email.split('@')[0] : 'Unknown');
}
function relationshipEvidence(type,summary,date='',confidence='medium',sourceId=''){
  return {type,summary:String(summary||'').slice(0,260),date:date||'',confidence,sourceId};
}
function interactionDate(value){
  const d=new Date(value||0);
  return isNaN(d.getTime()) ? 0 : d.getTime();
}
function daysSince(value){
  const t=interactionDate(value);
  if(!t) return null;
  return Math.floor((Date.now()-t)/(24*60*60*1000));
}
function splitPeopleFromText(text){
  const raw=String(text||'');
  const emails=(raw.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/ig)||[]).slice(0,8).map(email=>({name:'',email:email.toLowerCase(),confidence:'high'}));
  const names=[...raw.matchAll(/\b([A-Z][a-z]+(?:\s+[A-Z][a-z]+){1,3})\b/g)].map(m=>m[1])
    .map(collapseRepeatedName)
    .filter(v=>!/Google Calendar|Zoom Meeting|VAL|GHL|CRM|Make|OpenAI|Railway|Postgres|United States|New Lead|Relationship Review|Executive Review/.test(v))
    .slice(0,8).map(name=>({name,email:'',confidence:'low'}));
  const seen=new Set();
  return emails.concat(names).filter(p=>{const k=personKey(p.name,p.email);if(seen.has(k))return false;seen.add(k);return true;});
}
async function recentMemoryItems(days=30,limit=120){
  if(DEMO_MODE){
    const state=requestContext.getStore()?.demoState || {};
    const transcriptItems=(state.transcripts||[]).map(t=>({id:t.id,kind:t.type||'transcript',summary:t.title||'Transcript',rawText:t.rawText||'',metadata:t.metadata||{},createdAt:t.createdAt||''}));
    const memoryItems=state.memoryItems||[];
    return cloneDemo(memoryItems.concat(transcriptItems).slice(0,limit));
  }
  await valDbReady;
  const since=new Date(Date.now()-Number(days)*24*60*60*1000).toISOString();
  if(pgPool){
    const r=await dbQuery('select id,kind,summary,raw_text,metadata,created_at from val_memory_items where user_id=$1 and created_at >= $2 order by created_at desc limit $3',[VAL_USER_ID,since,limit]);
    return r.rows.map(row=>({id:row.id,kind:row.kind,summary:row.summary||'',rawText:row.raw_text||'',metadata:row.metadata||{},createdAt:row.created_at?row.created_at.toISOString():''}));
  }
  return (valStore().memoryItems||[]).filter(m=>new Date(m.createdAt||0)>=new Date(since)).slice(0,limit);
}
async function condenseOlderMemory(){
  await valDbReady;
  const cutoff=new Date(Date.now()-30*24*60*60*1000),items=[];
  if(DEMO_MODE)return {ok:true,created:0,keptOriginals:true,demo:true};
  if(pgPool){
    const r=await dbQuery("select id,kind,summary,raw_text,metadata,created_at from val_memory_items where user_id=$1 and created_at < $2 and kind <> 'memory_condensation' order by created_at asc limit 500",[VAL_USER_ID,cutoff.toISOString()]);
    items.push(...r.rows.map(x=>({id:x.id,kind:x.kind,summary:x.summary||'',rawText:x.raw_text||'',metadata:x.metadata||{},createdAt:x.created_at?.toISOString()||''})));
  }else items.push(...(valStore().memoryItems||[]).filter(x=>new Date(x.createdAt||0)<cutoff&&x.kind!=='memory_condensation').slice(0,500));
  if(!items.length)return {ok:true,created:0,keptOriginals:true};
  const groups={};items.forEach(item=>{const d=new Date(item.createdAt||0),key=isNaN(d)?'undated':d.toISOString().slice(0,7);(groups[key]=groups[key]||[]).push(item);});
  let created=0;
  for(const [month,rows] of Object.entries(groups)){
    const sourceIds=rows.map(x=>x.id),fingerprint=crypto.createHash('sha256').update(sourceIds.join('|')).digest('hex').slice(0,20);
    const existing=await recentMemoryItems(3650,1000).catch(()=>[]);if(existing.some(x=>x.kind==='memory_condensation'&&x.metadata?.fingerprint===fingerprint))continue;
    const highlights=rows.sort((a,b)=>Number(b.importance||1)-Number(a.importance||1)).slice(0,40).map(x=>`[${x.kind}] ${x.summary||String(x.rawText||'').slice(0,240)}`).join('\n');
    await saveMemoryItem({kind:'memory_condensation',summary:`Condensed VAL memory for ${month} (${rows.length} original items retained)`,rawText:highlights,importance:4,metadata:{fingerprint,month,sourceIds,sourceCount:rows.length,keptOriginals:true,condensedAt:new Date().toISOString()}});created++;
  }
  return {ok:true,created,sourceItems:items.length,keptOriginals:true};
}
function relationshipScore(contact){
  const ev=contact.evidence||[];
  const hasPipeline=ev.some(e=>e.type==='opportunity');
  const hasMeeting=ev.some(e=>e.type==='meeting');
  const hasEmail=ev.some(e=>e.type==='email');
  const hasNote=ev.some(e=>e.type==='note');
  const hasTranscript=ev.some(e=>e.type==='transcript');
  const openLoops=(contact.openLoops||[]).length;
  const tags=(contact.tags||[]).map(t=>String(t).toLowerCase());
  const vip=contact.manualVip||tags.some(t=>/vip|client|partner|investor|mentor|referral|decision|prospect/.test(t));
  const strategic=Math.min(25,(vip?14:0)+(hasPipeline?8:0)+(contact.company?2:0)+(contact.superConnector?5:0)+(openLoops?3:0));
  const opportunity=Math.min(20,(hasPipeline?12:0)+(ev.some(e=>/proposal|pricing|contract|partnership|referral|intro|revenue|buying/i.test(e.summary))?6:0)+(contact.superConnector?3:0));
  const activity=Math.min(15,(hasMeeting?4:0)+(hasEmail?4:0)+(hasNote?3:0)+(hasTranscript?3:0)+Math.min(ev.length,5));
  const since=daysSince(contact.lastInteractionAt);
  const drift=Math.min(15,((since!==null&&since>=14)?7:0)+((since!==null&&since>=30)?4:0)+(openLoops?4:0)+(ev.some(e=>/stalled|overdue|pending|waiting/i.test(e.summary))?4:0));
  const loops=Math.min(15,openLoops*4+(ev.some(e=>/follow up|send|review|schedule|introduce|proposal|pending|waiting/i.test(e.summary))?5:0));
  const reciprocity=Math.min(10,(ev.some(e=>/referral|introduced|introduction|connected/i.test(e.summary))?5:0)+(contact.superConnector?5:0));
  return {
    total:Math.min(100,Math.round(strategic+opportunity+activity+drift+loops+reciprocity)),
    strategicImportance:strategic,opportunityPotential:opportunity,relationshipActivity:activity,driftRisk:drift,openLoopsCommitments:loops,reciprocityBalance:reciprocity
  };
}
function recommendedRelationshipAction(contact){
  if((contact.openLoops||[]).length) return `Close the open loop: ${contact.openLoops[0]}`;
  if(contact.lastInteractionDays!==null&&contact.lastInteractionDays>=14) return `Send a specific reconnect note referencing ${contact.lastEvidenceSummary||'the last known conversation'}.`;
  if(contact.superConnector) return 'Ask what they are seeing in the market and whether there is someone useful you can support or introduce.';
  if(contact.scoreBreakdown?.opportunityPotential>=10) return 'Move the opportunity forward with one concrete next step.';
  return 'Send a short, specific value-add check-in.';
}
function draftRelationshipOutreach(contact){
  const name=(contact.name||'there').split(/\s+/)[0];
  const evidence=contact.lastEvidenceSummary||'our last conversation';
  const ask=(contact.openLoops||[])[0]||contact.recommendedAction||'keep momentum moving';
  return {
    type:'email',
    subject:`Quick follow-up${contact.company?' re: '+contact.company:''}`,
    body:`Hi ${name},\n\nI was thinking about ${evidence}. I wanted to follow up while it is still fresh.\n\n${ask}\n\nWould it be useful to compare notes for a few minutes this week?`
  };
}
function relationshipProfile(contact){
  return {
    name:contact.name,company:contact.company||'',email:contact.email||'',score:contact.score,scoreBreakdown:contact.scoreBreakdown,
    relationshipType:contact.relationshipType||'Professional',relationshipSummary:contact.reason,recentTopics:contact.topics||[],openLoops:contact.openLoops||[],
    lastMeaningfulInteraction:contact.lastInteractionAt||'',strategicValue:contact.strategicValue||'Evidence-based relationship priority.',
    opportunitySignals:contact.opportunitySignals||[],riskSignals:contact.riskSignals||[],suggestedNextAction:contact.recommendedAction,
    suggestedOutreach:contact.draftOutreach,relatedContacts:contact.relatedContacts||[],tags:contact.tags||[],evidence:contact.evidence||[],evidenceCount:(contact.evidence||[]).length,contactId:contact.contactId||contact.id||''
  };
}
function relationshipOwnerIdentity(){
  const emails=[process.env.ADMIN_EMAIL,process.env.VAL_OWNER_EMAIL,process.env.GMAIL_USER_EMAIL,process.env.OUTLOOK_USER_EMAIL]
    .concat(String(process.env.VAL_OWNER_ALIASES||'').split(',')).map(normalizeContextEmail).filter(Boolean);
  const names=[process.env.ADMIN_NAME,process.env.VAL_CLIENT_NAME,CLIENT_CONFIG.clientName,process.env.VAL_OWNER_NAME]
    .concat(String(process.env.VAL_OWNER_ALIASES||'').split(',')).map(normalizeContextName).filter(Boolean);
  return {emails:new Set(emails),names:new Set(names)};
}
function isOwnerRelationship(candidate={},owner=relationshipOwnerIdentity()){
  const email=normalizeContextEmail(candidate.email||candidate.contactEmail||'');
  const name=normalizeContextName(candidate.name||candidate.contactName||'');
  if(email&&owner.emails.has(email)) return true;
  if(name&&owner.names.has(name)) return true;
  if(name&&[...owner.names].some(alias=>looseNameScore(name,alias)>=0.8)) return true;
  return candidate.self===true||candidate.organizer===true&&(!email||owner.emails.has(email));
}
function isMeaningfulRelationshipEmail(email={}){
  const from=`${email.from?.name||''} ${email.from?.email||''}`.toLowerCase();
  const subject=String(email.subject||'').toLowerCase();
  if(/mailsuite|mailtrack|email tracking|tracking notification/.test(from+' '+subject)) return false;
  if(/^(opened:|email opened|link clicked|your email was opened)/.test(subject)) return false;
  return true;
}
function relationshipEmailParticipants(email={}){
  const values=[email.from,...(email.to||[]),...(email.cc||[])].filter(Boolean);
  return values.map(v=>({name:v.name||v.displayName||'',email:v.email||v.address||''}));
}
function synthesizeRelationshipSummary(contact={}){
  const types=[...new Set((contact.evidence||[]).map(e=>e.type))];
  const context=contact.company?`${contact.name} is connected to ${contact.company}.`:`${contact.name} is an external relationship worth understanding.`;
  const recent=contact.lastEvidenceSummary?` Recent activity includes ${String(contact.lastEvidenceSummary).replace(/\s+/g,' ').slice(0,180)}.`:'';
  const why=(contact.opportunitySignals||[]).length?' There is a live opportunity, referral, or partnership signal.':(contact.openLoops||[]).length?' An open commitment makes timely follow-through important.':` Evidence comes from ${types.join(', ')||'connected activity'}.`;
  return `${context}${recent}${why} ${contact.recommendedAction||'Review the relationship and choose one useful next move.'}`.replace(/\s+/g,' ').trim();
}
async function buildRelationshipReview({windowDays=7}={}){
  const now=new Date();
  const past=new Date(now);past.setDate(past.getDate()-Math.max(Number(windowDays)||7,7));
  const widerPast=new Date(now);widerPast.setDate(widerPast.getDate()-45);
  const future=new Date(now);future.setDate(future.getDate()+14);
  const people=new Map();
  const errors=[];
  const owner=relationshipOwnerIdentity();
  function touch({name='',email='',company='',tags=[]}){
    const cleanName=cleanPersonName(name,email),cleanEmail=normalizeContextEmail(email);
    if(isOwnerRelationship({name:cleanName,email:cleanEmail},owner)||(!cleanEmail&&(!cleanName||cleanName==='Unknown'))) return null;
    if(/^(no.?reply|notifications?|mailer-daemon)@/i.test(cleanEmail)) return null;
    const quality=relationshipContactQuality({email:{from:{name:cleanName,email:cleanEmail}},participant:{name:cleanName,email:cleanEmail},role:'from'});
    if(quality.hardRejected) return null;
    const normalizedName=normalizeContextName(cleanName),normalizedCompany=normalizeContextName(company);
    let p=[...new Set(people.values())].find(existing=>(cleanEmail&&existing.email===cleanEmail)||(normalizedName&&normalizeContextName(existing.name)===normalizedName)||(normalizedName&&normalizedCompany&&normalizeContextName(existing.company)===normalizedCompany&&looseNameScore(existing.name,cleanName)>=0.5));
    const key=personKey(cleanName,cleanEmail);
    if(!p){p={key,name:cleanName,email:cleanEmail,company:company||'',tags:[],evidence:[],openLoops:[],opportunitySignals:[],riskSignals:[],topics:[],relatedContacts:[]};}
    people.set(key,p);
    if(name&&(!p.name||p.name==='Unknown')) p.name=cleanPersonName(name,email);
    if(cleanEmail&&!p.email) p.email=cleanEmail;
    if(company&&!p.company) p.company=company;
    p.tags=Array.from(new Set((p.tags||[]).concat(tags||[]).filter(Boolean)));
    return p;
  }
  function addEvidence(person,evidence){
    if(!person||!evidence.summary)return;
    person.evidence.push(evidence);
    if(evidence.date&&interactionDate(evidence.date)>interactionDate(person.lastInteractionAt)) {
      person.lastInteractionAt=evidence.date;
      person.lastEvidenceSummary=evidence.summary;
    }
    if(/follow up|send|review|schedule|introduce|proposal|pending|waiting|owed|promised/i.test(evidence.summary)){
      person.openLoops=Array.from(new Set((person.openLoops||[]).concat(evidence.summary.slice(0,180)))).slice(0,8);
    }
    if(/proposal|pricing|contract|partnership|referral|intro|revenue|opportunity|pipeline/i.test(evidence.summary)) person.opportunitySignals.push(evidence.summary.slice(0,180));
    if(/stalled|overdue|waiting|no response|missed|forgotten|cooling/i.test(evidence.summary)) person.riskSignals.push(evidence.summary.slice(0,180));
    const topic=String(evidence.summary||'').split(/[.!?]/)[0].slice(0,90);
    if(topic) person.topics=Array.from(new Set((person.topics||[]).concat(topic))).slice(0,8);
  }
  const [gmail,outlook,tasks,transcripts,memory,preferenceMemory,ghlEvents,googleEvents,pipeline]=await Promise.all([
    fetchGmailMessages({query:'newer_than:45d',maxResults:60}).catch(e=>{errors.push('Gmail: '+e.message);return {emails:[],error:e.message};}),
    fetchUnifiedOutlookEmails(60).catch(e=>{errors.push('Outlook: '+e.message);return {emails:[],error:e.message};}),
    loadTasks().catch(e=>{errors.push('Tasks: '+e.message);return [];}),
    recentTranscripts(45).catch(e=>{errors.push('Transcripts: '+e.message);return [];}),
    recentMemoryItems(45,120).catch(e=>{errors.push('Memory: '+e.message);return [];}),
    recentMemoryItems(365,300).catch(()=>[]),
    fetchGhlCalendarEvents(widerPast,future).catch(e=>{errors.push('GHL calendar: '+e.message);return [];}),
    fetchGoogleCalendarEvents(widerPast,future,150).catch(e=>{errors.push('Google calendar: '+e.message);return [];}),
    fetchGhlOpportunities({status:'open',limit:100}).catch(e=>{errors.push('Pipeline: '+e.message);return {data:{opportunities:[]}};})
  ]);
  const preferences=new Map();
  for(const mem of preferenceMemory.filter(m=>m&&m.kind==='relationship_preference').sort((a,b)=>interactionDate(a.createdAt)-interactionDate(b.createdAt))){
    const pref=mem.metadata||parseLeadJson(mem.rawText)||{};const c=pref.contact||{};
    preferences.set(personKey(c.name,c.email),{action:pref.action||'',until:pref.until||'',createdAt:mem.createdAt||''});
  }
  for(const email of (gmail.emails||[]).concat(outlook.emails||[])){
    if(!email) continue;
    if(!isMeaningfulRelationshipEmail(email)) continue;
    const evidence=relationshipEvidence('email',`${email.subject||'(No subject)'}: ${email.snippet||email.bodyPreview||''}`,email.receivedAt||email.date,'high',email.messageId);
    relationshipEmailParticipants(email)
      .filter(person=>!isOwnerRelationship(person,owner))
      .filter(person=>relationshipContactQuality({email,participant:person,role:normalizeContextEmail(person.email)===normalizeContextEmail(email.from?.email)?'from':'to'}).accepted)
      .forEach(person=>addEvidence(touch(person),evidence));
  }
  for(const ev of ghlEvents.concat(googleEvents)){
    if(!ev) continue;
    inferAttendeesFromEvent(ev).forEach(a=>{
      const p=touch({name:a.name,email:a.email});
      addEvidence(p,relationshipEvidence('meeting',`${ev.title||ev.summary||'Meeting'}${ev.startTime?' on '+new Date(ev.startTime).toLocaleDateString('en-US'):''}`,ev.startTime,'high',ev.id));
    });
  }
  for(const task of tasks.filter(t=>t&&!t.completed)){
    const p=touch({name:task.contactName||''});
    if(!p||p.name==='Unknown') continue;
    addEvidence(p,relationshipEvidence('task',task.title+(task.notes?': '+task.notes:''),task.createdAt||task.dueDate,'high',task.id));
  }
  for(const tr of transcripts){
    if(!tr) continue;
    splitPeopleFromText([tr.title,tr.rawText].join(' ')).forEach(person=>{
      const p=touch(person);
      addEvidence(p,relationshipEvidence('transcript',`${tr.title||'Transcript'}: ${String(tr.rawText||'').slice(0,220)}`,tr.createdAt,person.confidence,tr.id));
    });
  }
  for(const mem of memory.filter(m=>m&&m.kind!=='relationship_preference')){
    splitPeopleFromText([mem.summary,mem.rawText].join(' ')).forEach(person=>{
      const p=touch(person);
      addEvidence(p,relationshipEvidence('memory',`${mem.summary||mem.kind}: ${String(mem.rawText||'').slice(0,220)}`,mem.createdAt,person.confidence,mem.id));
    });
  }
  for(const o of (pipeline.data?.opportunities||[])){
    if(!o) continue;
    const c=o.contact||{};
    const p=touch({name:c.name||o.contactName||o.name,email:c.email||o.contactEmail,company:o.name});
    addEvidence(p,relationshipEvidence('opportunity',`${o.name||'Open opportunity'}${o.monetaryValue?' worth $'+o.monetaryValue:''}${o.status?' is '+o.status:''}`,o.updatedAt||o.lastStatusChangeAt,'high',o.id));
  }
  for(const p of new Set(people.values())){
    const introCount=p.evidence.filter(e=>/intro|introduction|connect|referral|referred/i.test(e.summary)).length;
    p.superConnector=introCount>=2;
    if(p.superConnector) p.tags.push('Super Connector');
    p.lastInteractionDays=daysSince(p.lastInteractionAt);
    const pref=preferences.get(personKey(p.name,p.email))||preferences.get(personKey(p.name,''))||{};
    p.manualVip=pref.action==='mark_vip';p.notImportant=pref.action==='not_important';p.snoozedUntil=pref.action==='snooze'?pref.until:'';
    p.scoreBreakdown=relationshipScore(p);
    p.score=p.scoreBreakdown.total;
    if(p.manualVip){p.score=Math.min(100,p.score+20);p.tags.push('VIP');}
    if(p.notImportant)p.score=Math.max(0,p.score-40);
    p.recommendedAction=recommendedRelationshipAction(p);
    p.relationshipType=p.manualVip?'VIP':p.superConnector?'Connector':p.scoreBreakdown.opportunityPotential>=10?'Opportunity':p.company?'Professional':'Personal';
    p.reason=synthesizeRelationshipSummary(p);
    p.draftOutreach=draftRelationshipOutreach(p);
    p.profile=relationshipProfile(p);
  }
  const contacts=[...new Set(people.values())].filter(p=>p.name&&p.name!=='Unknown'&&p.evidence.length&&!isOwnerRelationship(p,owner)&&!p.notImportant&&(!p.snoozedUntil||new Date(p.snoozedUntil)<=now)).sort((a,b)=>b.score-a.score).slice(0,80);
  const topRelationshipPriorities=contacts.slice(0,10);
  const highestLeverageRelationships=contacts.filter(c=>c.scoreBreakdown.strategicImportance>=10||c.superConnector||c.scoreBreakdown.opportunityPotential>=10).slice(0,8);
  const coolingRelationships=contacts.filter(c=>c.lastInteractionDays!==null&&c.lastInteractionDays>=14&&c.score>=35).sort((a,b)=>b.score-a.score).slice(0,8);
  const momentumRelationships=contacts.filter(c=>c.evidence.filter(e=>interactionDate(e.date)>=past.getTime()).length>=2||c.scoreBreakdown.opportunityPotential>=10).slice(0,8);
  const peopleNotContactedRecently=contacts.filter(c=>c.lastInteractionDays!==null&&c.lastInteractionDays>=14).slice(0,10);
  const forgottenCommitments=contacts.flatMap(c=>(c.openLoops||[]).map(loop=>({contact:c.name,score:c.score,commitment:loop,sourceEvidence:c.evidence.find(e=>e.summary.includes(loop.slice(0,30)))||c.evidence[0],recommendedAction:`Close the loop with ${c.name}.`}))).slice(0,12);
  const hiddenOpportunities=contacts.filter(c=>(c.opportunitySignals||[]).length||c.superConnector).slice(0,10).map(c=>({contact:c.name,score:c.score,opportunity:(c.opportunitySignals||[])[0]||(c.superConnector?'Super Connector relationship may reveal introductions or market intelligence.':''),evidence:c.evidence.slice(0,2),recommendedAction:c.recommendedAction}));
  const connectors=contacts.filter(c=>c.superConnector);
  const opportunityPeople=contacts.filter(c=>c.scoreBreakdown.opportunityPotential>=8&&!c.superConnector);
  const suggestedIntroductions=connectors.slice(0,3).flatMap(a=>opportunityPeople.slice(0,3).filter(b=>b.key!==a.key).slice(0,1).map(b=>({personA:a.name,personB:b.name,reason:`${a.name} shows connector/referral signals and ${b.name} has opportunity signals.`,confidence:'low',evidence:[a.evidence[0],b.evidence[0]].filter(Boolean),suggestedIntroMessage:`${a.name}, I thought of you because ${b.name} is working through something that may overlap with your world. Would an introduction be useful?`}))).slice(0,5);
  return {
    ok:true,windowDays,generatedAt:new Date().toISOString(),errors,
    relationshipProfiles:contacts.map(c=>c.profile),
    topRelationshipPriorities,
    highestLeverageRelationships,
    coolingRelationships,
    momentumRelationships,
    peopleNotContactedRecently,
    forgottenCommitments,
    hiddenOpportunities,
    suggestedIntroductions,
    relationshipTaskPriorities:topRelationshipPriorities.map(c=>({contact:c.name,priority:c.score>=70?'High':c.score>=45?'Medium':'Low',tasks:c.openLoops||[],suggestedNextTask:c.recommendedAction,recommendedOutreach:c.draftOutreach})),
    draftCommunications:topRelationshipPriorities.slice(0,8).map(c=>({contact:c.name,score:c.score,draft:c.draftOutreach,evidence:c.evidence.slice(0,2)})),
    priorityReviewIntegration:{highestLeverageRelationship:highestLeverageRelationships[0]||null,top3RelationshipPriorities:topRelationshipPriorities.slice(0,3),oneCoolingRelationship:coolingRelationships[0]||null,oneForgottenCommitment:forgottenCommitments[0]||null,oneSuggestedIntroduction:suggestedIntroductions[0]||null,oneHiddenOpportunity:hiddenOpportunities[0]||null},
    askForAssistance:{question:'Would you like me to help with any of these relationships?',options:['Draft outreach','Create tasks','Brainstorm opportunities','Brainstorm ways to help this person','Prepare for upcoming meeting','Review relationship history']}
  };
}

function relationshipContactFromStoredProfile(profile={}){
  const openLoops=(profile.openLoops||[]).map(x=>x.content||x.summary||x.text||String(x)).filter(Boolean);
  const opportunities=(profile.opportunities||[]).map(x=>x.content||x.summary||x.text||String(x)).filter(Boolean);
  const risks=(profile.risks||[]).map(x=>x.content||x.summary||x.text||String(x)).filter(Boolean);
  const signals=(profile.relationshipSignals||[]).map(x=>x.content||x.summary||x.text||String(x)).filter(Boolean);
  const score=Math.min(100,Math.round(
    Math.min(35,Number(profile.openLoopCount||0)*9)+
    Math.min(25,Number(profile.opportunityCount||0)*8)+
    Math.min(25,Number(profile.riskCount||0)*8)+
    Math.min(15,Number(profile.observationCount||0)*2)
  ));
  const lastEvidenceSummary=openLoops[0]||opportunities[0]||risks[0]||signals[0]||profile.summary||'Stored relationship observation.';
  const contact={
    key:profile.profileKey,
    id:profile.personId||profile.id,
    contactId:profile.personId||'',
    name:profile.displayName||'Relationship',
    email:'',
    company:'',
    score,
    scoreBreakdown:{
      total:score,
      strategicImportance:Math.min(25,Number(profile.observationCount||0)*3),
      opportunityPotential:Math.min(20,Number(profile.opportunityCount||0)*7),
      relationshipActivity:Math.min(15,Number(profile.observationCount||0)*2),
      driftRisk:Math.min(15,Number(profile.riskCount||0)*6),
      openLoopsCommitments:Math.min(15,Number(profile.openLoopCount||0)*5),
      reciprocityBalance:0
    },
    relationshipType:profile.opportunityCount?'Opportunity':profile.riskCount?'Risk':profile.openLoopCount?'Open Loop':'Observed',
    lastInteractionAt:profile.lastObservedAt||profile.updatedAt||'',
    lastInteractionDays:daysSince(profile.lastObservedAt||profile.updatedAt),
    lastEvidenceSummary,
    openLoops,
    opportunitySignals:opportunities,
    riskSignals:risks,
    topics:signals.slice(0,6),
    tags:['Relationship Engine'],
    evidence:[{type:'relationship_engine',summary:lastEvidenceSummary,date:profile.lastObservedAt||profile.updatedAt,confidence:profile.confidence>=0.75?'high':'medium',sourceId:profile.id}],
    reason:profile.summary||`VAL has ${profile.observationCount||0} observation${Number(profile.observationCount||0)===1?'':'s'} connected to this relationship.`,
    recommendedAction:openLoops[0]?`Close the open loop: ${openLoops[0]}`:risks[0]?`Review the risk: ${risks[0]}`:opportunities[0]?`Move the opportunity forward: ${opportunities[0]}`:'Review the relationship history and choose one useful next move.'
  };
  contact.draftOutreach=draftRelationshipOutreach(contact);
  contact.profile=relationshipProfile(contact);
  return contact;
}
async function relationshipReviewFromStoredProfiles({windowDays=7}={}){
  const profiles=(await listRelationshipProfiles({limit:120})).filter(p=>p.profileType==='person');
  const contacts=profiles.map(relationshipContactFromStoredProfile).filter(c=>c.name&&c.name!=='Unknown').sort((a,b)=>b.score-a.score);
  const topRelationshipPriorities=contacts.slice(0,10);
  const highestLeverageRelationships=contacts.filter(c=>c.score>=35||c.openLoops.length||c.opportunitySignals.length||c.riskSignals.length).slice(0,8);
  const coolingRelationships=contacts.filter(c=>c.lastInteractionDays!==null&&c.lastInteractionDays>=14&&c.score>=20).slice(0,8);
  const momentumRelationships=contacts.filter(c=>c.opportunitySignals.length||c.topics.length).slice(0,8);
  const peopleNotContactedRecently=contacts.filter(c=>c.lastInteractionDays!==null&&c.lastInteractionDays>=14).slice(0,10);
  const forgottenCommitments=contacts.flatMap(c=>c.openLoops.map(loop=>({contact:c.name,score:c.score,commitment:loop,sourceEvidence:c.evidence[0],recommendedAction:`Close the loop with ${c.name}.`}))).slice(0,12);
  const hiddenOpportunities=contacts.filter(c=>c.opportunitySignals.length).slice(0,10).map(c=>({contact:c.name,score:c.score,opportunity:c.opportunitySignals[0],evidence:c.evidence,recommendedAction:c.recommendedAction}));
  return {
    ok:true,windowDays,generatedAt:new Date().toISOString(),source:'relationship_profiles',errors:[],
    relationshipProfiles:contacts.map(c=>c.profile),
    topRelationshipPriorities,
    highestLeverageRelationships,
    coolingRelationships,
    momentumRelationships,
    peopleNotContactedRecently,
    forgottenCommitments,
    hiddenOpportunities,
    suggestedIntroductions:[],
    relationshipTaskPriorities:topRelationshipPriorities.map(c=>({contact:c.name,priority:c.score>=70?'High':c.score>=45?'Medium':'Low',tasks:c.openLoops||[],suggestedNextTask:c.recommendedAction,recommendedOutreach:c.draftOutreach})),
    draftCommunications:topRelationshipPriorities.slice(0,8).map(c=>({contact:c.name,score:c.score,draft:c.draftOutreach,evidence:c.evidence.slice(0,2)})),
    priorityReviewIntegration:{highestLeverageRelationship:highestLeverageRelationships[0]||null,top3RelationshipPriorities:topRelationshipPriorities.slice(0,3),oneCoolingRelationship:coolingRelationships[0]||null,oneForgottenCommitment:forgottenCommitments[0]||null,oneSuggestedIntroduction:null,oneHiddenOpportunity:hiddenOpportunities[0]||null},
    askForAssistance:{question:'Would you like me to help with any of these relationships?',options:['Draft outreach','Create tasks','Brainstorm opportunities','Prepare for upcoming meeting','Review relationship history']}
  };
}

async function listRelationshipContactsForTranscript({limit=80}={}){
  const capped=Math.max(1,Math.min(Number(limit)||80,160));
  const profiles=(await listRelationshipProfiles({limit:capped})).filter(p=>p.profileType==='person');
  return profiles
    .map(relationshipContactFromStoredProfile)
    .filter(contact=>contact.contactId&&contact.name&&contact.name!=='Unknown')
    .slice(0,capped);
}

function transcriptBackfillParticipants(record={},detail={}){
  const fromDetail=(detail.participants||[]).map(p=>({
    role:'participant',
    name:p.matchedContactName||p.speakerNameRaw||'',
    email:p.matchedEmail||'',
    matchedContactId:p.matchedContactId||'',
    matchedCompany:p.matchedCompany||''
  })).filter(p=>p.name||p.email||p.matchedContactId);
  if(fromDetail.length)return fromDetail;
  return splitPeopleFromText([record.title,record.rawText,JSON.stringify(record.metadata||{})].join(' ')).slice(0,12).map(p=>({role:'mentioned',name:p.name||'',email:p.email||'',confidence:p.confidence||'low'}));
}
function transcriptEvidenceSnippet(text='',pattern){
  const clean=String(text||'').replace(/\s+/g,' ').trim();
  if(!clean)return '';
  const sentences=clean.split(/(?<=[.!?])\s+/).map(s=>s.trim()).filter(Boolean);
  const commandLike=/^(prepare me for|summarize this|good morning|here'?s your situation|daily briefing)\b/i;
  const found=sentences.find(s=>pattern.test(s)&&!commandLike.test(s));
  const snippet=found||sentences.find(s=>pattern.test(s))||'';
  return snippet.length>220?snippet.slice(0,217).replace(/\s+\S*$/,'')+'...':snippet;
}
function transcriptFallbackObservationContent(type,record={},text='',pattern){
  const snippet=transcriptEvidenceSnippet(text,pattern);
  const subject=snippet||transcriptTopicTitleFromText(text)||valTitleCandidate(record.title)||'Transcript evidence';
  if(type==='risk')return `Possible risk: ${subject}`;
  if(type==='opportunity')return `Possible opportunity: ${subject}`;
  if(type==='pricing_question')return `Pricing or proposal context: ${subject}`;
  return subject;
}
function transcriptBackfillCandidates(record={},participants=[]){
  const text=String(record.rawText||'');
  const candidates=[];
  extractOpenLoopsFromText(text,'transcript',record.createdAt||record.metadata?.timestamp||'').forEach(loop=>{
    candidates.push({observationType:/follow up|circle back|waiting on/i.test(loop.text)?'follow_up':'task',content:loop.text,exactQuote:transcriptSupportingQuote(text,loop.text),confidence:loop.confidence==='high'?0.82:0.65,status:'open'});
  });
  const pricingPattern=/\b(price|pricing|cost|budget|proposal|contract)\b/i,riskPattern=/\b(risk|concern|worried|blocked|stuck|drift|confused|not working)\b/i,opportunityPattern=/\b(opportunity|intro|introduction|referral|partner|lead|client|deal)\b/i;
  if(pricingPattern.test(text))candidates.push({observationType:'pricing_question',content:transcriptFallbackObservationContent('pricing_question',record,text,pricingPattern),exactQuote:transcriptSupportingQuote(text,'pricing'),confidence:0.68,status:'needs_review'});
  if(riskPattern.test(text))candidates.push({observationType:'risk',content:transcriptFallbackObservationContent('risk',record,text,riskPattern),exactQuote:transcriptSupportingQuote(text,'risk'),confidence:0.62,status:'needs_review'});
  if(opportunityPattern.test(text))candidates.push({observationType:'opportunity',content:transcriptFallbackObservationContent('opportunity',record,text,opportunityPattern),exactQuote:transcriptSupportingQuote(text,'opportunity'),confidence:0.66,status:'needs_review'});
  if(!candidates.length&&participants.length)candidates.push({observationType:'relationship_signal',content:`${record.title||'Transcript'} contains relationship context that should be available to VAL.`,exactQuote:transcriptSupportingQuote(text,record.title||''),confidence:0.55,status:'observed'});
  return candidates.slice(0,30);
}
function transcriptMigrationRecordsFromIndex(index={}){
  return (index.transcripts||[]).map(row=>{
    const detail=transcriptDetailFromIndex(index,row);
    return {
      id:detail.id||row.transcriptId,
      type:'transcript',
      title:detail.title||row.meetingTitle||'Recovered transcript',
      rawText:detail.transcriptText||row.rawTranscript||'',
      metadata:{
        source:row.source||'transcript_index',
        timestamp:row.meetingDatetime||row.createdAt||'',
        calendarEventId:row.calendarEventId||'',
        processingStatus:row.processingStatus||'',
        summaryStatus:row.summaryStatus||'',
        recoveredFrom:'transcript_index'
      },
      createdAt:row.meetingDatetime||row.createdAt||row.updatedAt||'',
      detail
    };
  }).filter(record=>record.id&&String(record.rawText||'').trim());
}
function mergeTranscriptMigrationRecords(records=[],index={}){
  const byId=new Map();
  for(const record of transcriptMigrationRecordsFromIndex(index))byId.set(String(record.id),record);
  for(const record of records||[]){
    if(!record?.id)continue;
    const id=String(record.id),existing=byId.get(id);
    if(existing){
      byId.set(id,{
        ...record,
        ...existing,
        title:existing.title||record.title,
        rawText:existing.rawText||record.rawText,
        metadata:{...(record.metadata||{}),...(existing.metadata||{})},
        createdAt:existing.createdAt||record.createdAt
      });
    }else byId.set(id,record);
  }
  return [...byId.values()].sort((a,b)=>interactionDate(b.createdAt||b.metadata?.timestamp)-interactionDate(a.createdAt||a.metadata?.timestamp));
}
async function backfillTranscriptEvidence({days=3650,limit=250}={}){
  const [records,index]=await Promise.all([transcriptArchiveRecords(days,limit),transcriptIndexData().catch(()=>({transcripts:[],participants:[],summaries:[],tasks:[],contactUpdates:[],actionLog:[]}))]);
  const migrationRecords=mergeTranscriptMigrationRecords(records,index).slice(0,limit);
  let processed=0,observations=0,relationshipEvents=0,agencyMoves=0,errors=[],found=migrationRecords.length;
  for(const record of migrationRecords){
    try{
      const detailRow=(index.transcripts||[]).find(t=>String(t.transcriptId)===String(record.id));
      const detail=record.detail||(detailRow?transcriptDetailFromIndex(index,detailRow):{});
      const title=detail.title||record.title||'Recovered transcript';
      const rawText=detail.transcriptText||record.rawText||'';
      if(!rawText.trim())continue;
      const participants=transcriptBackfillParticipants(record,detail);
      const summary=detail.summary||{};
      const parsed={
        keyDecisions:summary.keyDecisions||[],
        openQuestions:summary.openQuestions||[],
        relationshipUpdates:summary.relationshipUpdates||[],
        tasks:(detail.tasks||[]).map(t=>({taskTitle:t.taskTitle,content:t.taskTitle,sourceQuote:t.sourceQuote,assignedToName:t.assignedToName,dueDate:t.dueDate,confidence:t.confidence,status:t.status||'open'})),
        contactUpdates:detail.contactUpdates||[],
        actionItems:[]
      };
      await saveEvidenceItem({sourceType:'transcript',sourceId:record.id,occurredAt:detail.meetingDatetime||record.metadata?.timestamp||record.createdAt||null,capturedAt:record.createdAt||new Date().toISOString(),title,rawText,summary:summary.executiveSummary||record.metadata?.summary||'',participantsJson:participants,entitiesJson:{source:'backfill',legacyTranscriptId:record.id,participantCount:participants.length},confidence:0.72,status:'backfilled',metadataJson:{source:'backfill',type:record.type||'',recoveredFrom:record.metadata?.recoveredFrom||''}});
      let saved=[];
      if((parsed.keyDecisions.length||parsed.openQuestions.length||parsed.relationshipUpdates.length||parsed.tasks.length||parsed.contactUpdates.length)){
        saved=await saveTranscriptEvidenceObservations({sourceId:record.id,title,transcript:rawText,parsed,participants,summary});
      }else{
        const evidence=await evidenceItemForSource('transcript',record.id);
        const result=await runObservationEngine(evidence,{candidates:transcriptBackfillCandidates({...record,title,rawText},participants),replace:true});
        saved=result.observations||[];
        relationshipEvents+=result.relationshipEngine?.events?.length||0;
        agencyMoves+=result.agencyEngine?.moves?.length||0;
      }
      processed++;
      observations+=saved.length;
    }catch(e){errors.push({sourceId:record.id,title:record.title||'',error:e.message});}
  }
  return {found,processed,observations,relationshipEvents,agencyMoves,errors};
}
function uniqueEmailsByMessageId(results=[]){
  const seen=new Set(),emails=[];
  for(const result of results){
    for(const email of (result&&result.emails)||[]){
      const key=[email.provider||'',email.messageId||email.id||'',email.threadId||''].join(':');
      if(!email.messageId||seen.has(key))continue;
      seen.add(key);emails.push(email);
    }
  }
  return emails;
}
async function backfillEmailEvidence({days=90,limit=100}={}){
  const gmailRecent=`newer_than:${Math.max(1,Math.min(365,Number(days)||90))}d`;
  const [rules,recent,unread,sent,outlook]=await Promise.all([
    listEmailRules(currentUserId()).catch(()=>[]),
    fetchGmailMessages({query:gmailRecent,maxResults:limit,includeBody:true}).catch(e=>({emails:[],error:e.message,provider:'gmail'})),
    fetchGmailMessages({query:'is:unread',maxResults:Math.min(limit,100),includeBody:true}).catch(e=>({emails:[],error:e.message,provider:'gmail'})),
    fetchGmailMessages({query:`in:sent newer_than:${Math.max(1,Math.min(365,Number(days)||90))}d`,maxResults:Math.min(limit,100),includeBody:true}).catch(e=>({emails:[],error:e.message,provider:'gmail'})),
    fetchUnifiedOutlookEmails(Math.min(limit,100)).catch(e=>({emails:[],error:e.message,provider:'outlook'}))
  ]);
  const providerErrors=[recent,unread,sent,outlook].filter(r=>r&&r.error).map(r=>({provider:r.provider||'email',error:r.error}));
  const emailCorpus=uniqueEmailsByMessageId([recent,unread,sent,outlook]);
  const emails=emailCorpus.map(email=>{
    const withMetrics={...email,senderMetrics:emailSenderMetrics(email,emailCorpus)};
    return {...withMetrics,...classifyExecutiveEmail(withMetrics,rules)};
  });
  const saved=await saveEmailEvidenceBatch(emails);
  const relationshipIntake=saved.reduce((acc,result)=>{
    const intake=result?.relationshipIntake||{};
    acc.relationshipProfiles+=Number(intake.relationshipProfiles||0);
    acc.personPackets+=Number(intake.personPackets||0);
    acc.personPacketIds.push(...(Array.isArray(intake.personPacketIds)?intake.personPacketIds:[]));
    return acc;
  },{relationshipProfiles:0,personPackets:0,personPacketIds:[]});
  relationshipIntake.personPacketIds=[...new Set(relationshipIntake.personPacketIds)].slice(0,120);
  const projectManagerIntake=await processEmailDocumentSourceProcessing(emails,{origin:'email_backfill'}).catch(error=>({ok:false,origin:'email_backfill',processed:0,eligible:0,suggestions:0,skipped:0,errors:[error.message],noExternalAction:true}));
  return {processed:emails.length,saved:saved.filter(Boolean).length,relationshipIntake,sourceProcessing:{projectManagers:projectManagerIntake},providerErrors};
}
async function backfillValIntelligence(options={}){
  if(!DEMO_MODE&&!pgPool)throw new Error('Postgres is not connected. Attach Railway Postgres and confirm DATABASE_URL before backfilling VAL intelligence.');
  const days=Math.max(1,Math.min(3650,Number(options.days)||3650));
  const transcriptLimit=Math.max(1,Math.min(500,Number(options.transcriptLimit)||250));
  const emailLimit=Math.max(1,Math.min(100,Number(options.emailLimit)||100));
  const [transcripts,email]=await Promise.all([
    options.skipTranscripts?Promise.resolve({processed:0,observations:0,relationshipEvents:0,agencyMoves:0,errors:[]}):backfillTranscriptEvidence({days,limit:transcriptLimit}),
    options.skipEmail?Promise.resolve({processed:0,saved:0,providerErrors:[]}):backfillEmailEvidence({days:Math.min(days,365),limit:emailLimit})
  ]);
  const [counts,briefing,storedRelationships]=await Promise.all([
    executiveBriefingCounts(),
    buildExecutiveBriefing().catch(()=>null),
    relationshipReviewFromStoredProfiles({windowDays:Math.min(days,90)}).catch(()=>null)
  ]);
  return {ok:true,generatedAt:new Date().toISOString(),days,transcripts,email,counts,relationshipProfiles:storedRelationships?.relationshipProfiles?.length||0,highestLeverageMove:briefing?.highestLeverageMove||null};
}

function mapGoogleEvent(ev){
  return {
    id:ev.id, summary:ev.summary||'(No title)',
    startTime:ev.start?.dateTime||ev.start?.date,
    endTime:ev.end?.dateTime||ev.end?.date,
    location:ev.location||'',
    description:ev.description||'',
    attendees:(ev.attendees||[]).map(a=>({name:a.displayName||'',email:a.email||'',responseStatus:a.responseStatus||'',self:!!a.self,organizer:!!a.organizer})),
    attendeesOmitted:!!ev.attendeesOmitted,
    organizer:ev.organizer?{name:ev.organizer.displayName||'',email:ev.organizer.email||'',self:!!ev.organizer.self}:null,
    creator:ev.creator?{name:ev.creator.displayName||'',email:ev.creator.email||'',self:!!ev.creator.self}:null,
    hangoutLink:ev.hangoutLink||'',
    status:ev.status, source:'google'
  };
}

async function hydrateGoogleEventAttendees(token,ev){
  if(ev.attendees&&ev.attendees.length&&!ev.attendeesOmitted) return ev;
  try{
    const r=await fetch(`https://www.googleapis.com/calendar/v3/calendars/primary/events/${encodeURIComponent(ev.id)}?maxAttendees=50`,{headers:{Authorization:`Bearer ${token}`}});
    const full=await r.json();
    if(!full.error) return {...ev,...full};
  }catch(e){console.log('Google event attendee hydrate failed:',e.message);}
  return ev;
}

function extractLinkedInUrl(data){
  const text = JSON.stringify(data||{});
  return (text.match(/https?:\/\/([a-z]+\.)?linkedin\.com\/in\/[^"',\s)]+/i)||[])[0] || '';
}

function extractEmailsFromValue(value){
  const text = typeof value === 'string' ? value : JSON.stringify(value||'');
  const matches = text.match(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi) || [];
  return [...new Set(matches.map(e=>e.toLowerCase())
    .filter(e=>!/\.(png|jpg|jpeg|gif|webp|svg|css|js)$/i.test(e))
    .filter(e=>!/(example|domain|email\.com|sentry|wixpress|wordpress|schema\.org)/i.test(e)))];
}

function firstEmailFrom(...values){
  for(const value of values){
    const found = extractEmailsFromValue(value);
    if(found.length) return found[0];
  }
  return '';
}

function isLikelyPersonEmail(email){
  const local = String(email||'').split('@')[0].toLowerCase();
  if(!local) return false;
  if(/^(info|hello|contact|support|admin|office|team|media|press|help|careers|jobs|webmaster|noreply|no-reply|service|services|customerservice|sales|billing|accounts|dispatch|schedule|scheduling|quotes?|estimating|appointments?|mail|inquiries?)$/.test(local)) return false;
  if(/^(owner|founder|ceo|president|director)$/.test(local)) return false;
  const domain=String(email||'').split('@')[1]||'';
  const freeDomain=/^(gmail|yahoo|outlook|hotmail|icloud|aol)\./i.test(domain);
  if(freeDomain && /(electric|electrical|plumb|plumbing|hvac|heating|cooling|roof|roofing|contract|contractor|construction|service|services|llc|inc|az|phoenix|mesa|chandler|company|shop|repair|drain)/i.test(local)) return false;
  if(/(electric|electrical|plumb|plumbing|hvac|roof|contractor|construction|service|services|llc|inc|company)/i.test(local) && !/[._-]/.test(local)) return false;
  return true;
}

function classifyEmail(email){
  if(!email) return 'missing';
  const local=String(email).split('@')[0].toLowerCase();
  if(isLikelyPersonEmail(email)) return 'person';
  if(/^(sales|partnerships|bizdev|businessdevelopment|hr|humanresources|benefits|operations|ops|owner|founder|ceo|president|director)$/.test(local)) return 'high-value role';
  return 'general';
}

function leadContactability(lead={}){
  const rawEmail=lead.email||lead.verifiedEmail||'';
  const rawPhone=lead.phone||lead.verifiedPhone||'';
  const hasEmail=validEmail(rawEmail);
  const hasPhone=validPhone(rawPhone);
  let contactabilityStatus='not_contactable';
  if(hasEmail&&hasPhone) contactabilityStatus='full_contactability';
  else if(hasEmail) contactabilityStatus='email_only';
  else if(hasPhone) contactabilityStatus='phone_only';
  return {
    contactabilityStatus,
    hasEmail,
    hasPhone,
    emailEligibility:hasEmail,
    phoneEligibility:hasPhone,
    initialEmailSent:hasEmail,
    email:hasEmail?normalizeEmailAddress(rawEmail):'',
    phone:hasPhone?normalizePhoneNumber(rawPhone):'',
    importable:true,
    rejectionReason:''
  };
}

function leadContactabilityNote(c){
  if(c.contactabilityStatus==='full_contactability') return 'Email and phone available. Lead eligible for automated email, SMS, AI calling, and manual outreach.';
  if(c.contactabilityStatus==='email_only') return 'Email available. No valid phone number found. Lead eligible for automated email and manual email outreach.';
  if(c.contactabilityStatus==='phone_only') return 'No email address found. Lead did not receive the initial automated email sequence. Lead should enter phone-first outreach workflows and is eligible for AI calling, SMS outreach, and manual calling.';
  return 'No email or phone number was found. Lead imported for visibility, but it is not eligible for automated email, SMS, AI calling, or manual contact until a contact method is added.';
}

function normalizeRocketReachPerson(data){
  const person = data.person || data.profile || data.data || data;
  const emails = extractEmailsFromValue(person);
  const phones = [...new Set(JSON.stringify(person||'').match(/(?:\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}/g)||[])];
  const company = person.current_employer || person.current_company || person.company || {};
  const companyObj = typeof company === 'object' ? company : {};
  return {
    found: !!(person && Object.keys(person).length),
    id: person.id || person.profile_id || '',
    name: person.name || person.full_name || [person.first_name,person.last_name].filter(Boolean).join(' '),
    title: person.current_title || person.title || person.job_title || '',
    company: typeof company === 'string' ? company : (companyObj.name || companyObj.company_name || ''),
    location: person.location || person.city || '',
    linkedinUrl: person.linkedin_url || person.linkedin || extractLinkedInUrl(person),
    email: emails.find(isLikelyPersonEmail) || emails[0] || '',
    phone: phones[0] || '',
    connections: person.connections || person.num_connections || person.linkedin_connections || null,
    mutualConnections: person.mutual_connections || person.shared_connections || person.common_connections || null,
    companyLinkedInUrl: companyObj.linkedin_url || companyObj.linkedin || person.company_linkedin_url || '',
    companyId: companyObj.id || companyObj.profile_id || person.company_id || '',
    employeeCount: companyObj.employees || companyObj.employee_count || companyObj.num_employees || person.company_employee_count || '',
    companySizeBand: companyObj.size || companyObj.company_size || companyObj.employee_range || '',
    companyDescription: companyObj.description || person.company_description || '',
    companyLocation: companyObj.location || companyObj.city || person.company_location || '',
    companyFoundedYear: companyObj.founded || companyObj.founded_year || person.company_founded_year || '',
    rawPreview: JSON.stringify(person).slice(0,1400)
  };
}

async function lookupRocketReach(attendee){
  const rocketReachKey=await resolveIntegrationSecret('rocketreach','api_key',ROCKETREACH_API_KEY);
  if(!rocketReachKey) return {configured:false, error:'ROCKETREACH_API_KEY is not set'};
  if(Date.now()<rocketReachLimitedUntil) return {configured:true, error:'RocketReach rate-limited; skipped to protect quota'};
  const params = new URLSearchParams();
  if(attendee.email) params.set('email',attendee.email);
  if(attendee.linkedinUrl) params.set('linkedin_url',attendee.linkedinUrl);
  if(attendee.name) params.set('name',attendee.name);
  if(attendee.company) params.set('current_employer',attendee.company);
  if(attendee.title || attendee.currentTitle) params.set('current_title',attendee.title || attendee.currentTitle);
  const url = `${ROCKETREACH_BASE_URL.replace(/\/$/,'')}/person/lookup?${params.toString()}`;
  let response;
  let data={};
  for(let attempt=0;attempt<2;attempt+=1){
    response=await fetchWithTimeout(url,{headers:{'Api-Key':rocketReachKey}},ROCKETREACH_REQUEST_TIMEOUT_MS,'RocketReach lookup');
    data=await readJsonResponse(response);
    if(![502,503,504].includes(response.status) || attempt===1) break;
    await sleep(750);
  }
  if(response.status===429){
    rocketReachLimitedUntil = Date.now() + 10*60*1000;
    return {configured:true, error:'RocketReach 429 rate limit'};
  }
  if(!response.ok) return {configured:true, error:data.message || data.error || `RocketReach ${response.status}`};
  return {configured:true, data:normalizeRocketReachPerson(data)};
}

async function lookupRocketReachDecisionMaker(company,lead={},options={}){
  const titles=[
    'Owner',
    'Founder',
    'CEO',
    'President',
    'Director of Operations'
  ];
  if(lead.decisionMakerName || lead.linkedinPersonalUrl || isLikelyPersonEmail(lead.email)){
    const exact=await lookupRocketReach({
      name:lead.decisionMakerName,
      company,
      email:isLikelyPersonEmail(lead.email)?lead.email:'',
      linkedinUrl:lead.linkedinPersonalUrl
    }).catch(e=>({configured:!!ROCKETREACH_API_KEY,error:e.message}));
    if(exact.data?.name || exact.data?.email || exact.data?.phone) return {...exact,matchTitle:lead.decisionMakerTitle||''};
  }
  const maxTitleLookups=Math.min(Math.max(Number(options.maxTitleLookups)||titles.length,1),titles.length);
  for(const title of titles.slice(0,maxTitleLookups)){
    const rr=await lookupRocketReach({company,name:'',title,currentTitle:title}).catch(e=>({configured:!!ROCKETREACH_API_KEY,error:e.message}));
    if(rr.error && /rate limit/i.test(rr.error)) return rr;
    if(rr.data?.name || rr.data?.email || rr.data?.phone) return {...rr,matchTitle:title};
  }
  return {configured:!!(await resolveIntegrationSecret('rocketreach','api_key',ROCKETREACH_API_KEY).catch(()=>'')), error:'No decision-maker match found'};
}

function normalizeCompanyForMatch(value){
  return String(value||'')
    .toLowerCase()
    .replace(/&/g,' and ')
    .replace(/\b(inc|incorporated|llc|l\.l\.c|ltd|limited|corp|corporation|co|company|pllc|pc|pa|llp|lp)\b/g,' ')
    .replace(/[^a-z0-9]+/g,' ')
    .replace(/\s+/g,' ')
    .trim();
}

function apolloPersonTitles(){
  return [
    'Owner',
    'Founder',
    'CEO',
    'President',
    'Managing Partner',
    'Partner',
    'Principal',
    'Practice Owner',
    'Executive Director',
    'General Manager',
    'Operations Manager',
    'Director of Operations',
    'HR Director',
    'Human Resources Director',
    'Office Manager'
  ];
}

function normalizeApolloPerson(person,lead={}){
  const org=person.organization || person.account || person.current_organization || {};
  const name=person.name || person.full_name || [person.first_name,person.last_name].filter(Boolean).join(' ');
  return {
    found:!!(name || person.linkedin_url || person.title),
    id:person.id || person.person_id || '',
    name:name||'',
    title:person.title || person.current_title || person.headline || '',
    company:org.name || person.organization_name || person.company || '',
    companyDomain:org.primary_domain || org.website_url || org.domain || leadDomain(lead.website||''),
    linkedinUrl:person.linkedin_url || person.linkedin || '',
    city:person.city || '',
    state:person.state || '',
    country:person.country || '',
    emailStatus:person.email_status || person.contact_email_status || '',
    rawPreview:JSON.stringify(person).slice(0,1400)
  };
}

function scoreApolloPerson(person,lead){
  let score=0;
  const title=String(person.title||'').toLowerCase();
  if(/\b(owner|founder|ceo|chief executive|president)\b/.test(title)) score+=100;
  else if(/\b(managing partner|partner|principal|practice owner|executive director)\b/.test(title)) score+=85;
  else if(/\b(operations|general manager|office manager|human resources|hr director)\b/.test(title)) score+=60;
  else if(/\b(manager|director)\b/.test(title)) score+=35;
  const targetDomain=leadDomain(lead.website||'');
  const personDomain=leadDomain(person.companyDomain||'');
  if(targetDomain && personDomain && targetDomain===personDomain) score+=120;
  const targetCompany=normalizeCompanyForMatch(lead.organizationName||lead.name||'');
  const personCompany=normalizeCompanyForMatch(person.company||'');
  if(targetCompany && personCompany){
    if(targetCompany===personCompany) score+=90;
    else if(targetCompany.includes(personCompany) || personCompany.includes(targetCompany)) score+=55;
  }
  if(person.linkedinUrl) score+=12;
  if(person.name) score+=10;
  return score;
}

async function lookupApolloDecisionMaker(lead={}){
  const apolloKey=await resolveIntegrationSecret('apollo','api_key',APOLLO_API_KEY);
  if(!apolloKey) return {configured:false,error:'APOLLO_API_KEY is not set'};
  const domain=leadDomain(lead.website||'');
  const company=lead.organizationName||lead.name||'';
  const params=new URLSearchParams();
  apolloPersonTitles().forEach(title=>params.append('person_titles[]',title));
  ['owner','founder','c_suite','partner','vp','head','director','manager'].forEach(s=>params.append('person_seniorities[]',s));
  if(domain) params.append('q_organization_domains_list[]',domain);
  if(!domain && company) params.set('q_keywords',company);
  if(lead.state) params.append('organization_locations[]',lead.state);
  else if(lead.location) params.append('organization_locations[]',lead.location);
  params.set('include_similar_titles','false');
  params.set('page','1');
  params.set('per_page','10');
  const url=`${APOLLO_BASE_URL.replace(/\/$/,'')}/mixed_people/api_search?${params.toString()}`;
  const response=await fetchWithTimeout(url,{
    method:'POST',
    headers:{
      accept:'application/json',
      'Content-Type':'application/json',
      'x-api-key':apolloKey,
      Authorization:`Bearer ${apolloKey}`
    }
  },APOLLO_REQUEST_TIMEOUT_MS,'Apollo decision-maker lookup');
  const data=await readJsonResponse(response);
  if(!response.ok) return {configured:true,error:data.message || data.error || `Apollo ${response.status}`};
  const rawPeople=[...(data.people||[]),...(data.contacts||[]),...(data.persons||[])];
  const people=rawPeople.map(p=>normalizeApolloPerson(p,lead)).filter(p=>p.found);
  const ranked=people
    .map(p=>({...p,matchScore:scoreApolloPerson(p,lead)}))
    .filter(p=>p.matchScore>=70 || (domain && leadDomain(p.companyDomain||'')===domain))
    .sort((a,b)=>b.matchScore-a.matchScore);
  if(!ranked.length) return {configured:true,error:'Apollo did not find a confident decision-maker match',rawCount:rawPeople.length};
  return {configured:true,data:ranked[0],candidates:ranked.slice(0,3),rawCount:rawPeople.length};
}

async function enrichProspectWithApollo(p){
  if(p.decisionMakerName || p.linkedinPersonalUrl) return p;
  const apollo=await lookupApolloDecisionMaker(p).catch(e=>({configured:!!APOLLO_API_KEY,error:e.message}));
  const data=apollo?.data||{};
  if(!data.name && !data.linkedinUrl){
    return {
      ...p,
      apollo,
      apolloStatus:apollo?.error||'Apollo did not return a decision-maker'
    };
  }
  return {
    ...p,
    decisionMakerName:p.decisionMakerName||data.name||'',
    decisionMakerTitle:p.decisionMakerTitle||data.title||'',
    linkedinPersonalUrl:p.linkedinPersonalUrl||data.linkedinUrl||'',
    linkedinMatchConfidence:data.matchScore>=160?'high':'medium',
    linkedinMatchNotes:`Apollo matched ${data.name||'a likely contact'}${data.title?' - '+data.title:''}${data.company?' at '+data.company:''}`,
    apollo,
    apolloStatus:`matched ${data.name||'likely decision-maker'}${data.title?' - '+data.title:''}`
  };
}

async function lookupOutscraperLinkedIn(attendee, profile){
  const outscraperKey=await resolveIntegrationSecret('outscraper','api_key',OUTSCRAPER_API_KEY);
  if(!outscraperKey) return {configured:false, error:'OUTSCRAPER_API_KEY is not set'};
  if(!OUTSCRAPER_LINKEDIN_POSTS_URL) return {configured:false, error:'OUTSCRAPER_LINKEDIN_POSTS_URL is not set'};
  const url = new URL(OUTSCRAPER_LINKEDIN_POSTS_URL);
  const organization = profile?.company || profile?.organization || profile?.metadata?.company || profile?.metadata?.organization || '';
  const email=normalizeContextEmail(attendee.email||relationshipProfilePrimaryEmail(profile)||'');
  const domain=String(email.split('@')[1]||'').replace(/^www\./i,'').toLowerCase();
  const usableDomain=domain&&!/(gmail|googlemail|yahoo|outlook|hotmail|icloud|me|mac|aol|protonmail)\./i.test(domain)?domain:'';
  const name=firstLookCandidateCleanName(attendee.name||profile?.displayName||profile?.display_name||profile?.name||'');
  const personalLinkedIn=profile?.linkedinUrl || attendee.linkedinUrl || profile?.linkedin_url || '';
  const companyLinkedIn=profile?.companyLinkedInUrl || profile?.company_linkedin_url || profile?.metadata?.companyLinkedInUrl || profile?.metadata?.company_linkedin_url || '';
  const endpointLooksCompany=/linkedin-posts/i.test(OUTSCRAPER_LINKEDIN_POSTS_URL);
  const query = endpointLooksCompany
    ? (companyLinkedIn || [name, organization || usableDomain].filter(Boolean).join(' ') || organization || usableDomain || name || email)
    : (personalLinkedIn || [name, organization || usableDomain].filter(Boolean).join(' ') || name || email);
  if(query) url.searchParams.set('query', query);
  url.searchParams.set('async','false');
  const response = await fetchWithTimeout(url.toString(),{headers:{'X-API-KEY':outscraperKey}},OUTSCRAPER_SUBMIT_TIMEOUT_MS,'Outscraper LinkedIn posts');
  const data = await readJsonResponse(response);
  if(!response.ok) return {configured:true, error:data.errorMessage || data.message || `Outscraper ${response.status}`};
  const posts = Array.isArray(data.data) ? data.data.flat(3).filter(Boolean) : [];
  const recentPosts = posts.slice(0,6).map(p=>({
    date:p.date || p.posted_at || p.created_at || '',
    text:String(p.text || p.post_text || p.content || p.description || p.title || '').slice(0,700),
    url:p.url || p.post_url || p.link || ''
  }));
  return {configured:true, query, postsLastWeek:recentPosts, rawCount:posts.length};
}

function meetingPrepPublicSearchQueries(attendee={}, contact={}, profile={}){
  const email=normalizeContextEmail(attendee.email||contact.email||relationshipProfilePrimaryEmail(profile)||'');
  const name=firstLookCandidateCleanName(attendee.name||contact.name||profile.displayName||profile.display_name||profile.name||'');
  const organization=firstLookCandidateCleanName(
    contact.company||contact.organization||profile.company||profile.organization||profile.metadata?.company||profile.metadata?.organization||''
  );
  const domain=String(email.split('@')[1]||'').replace(/^www\./i,'').toLowerCase();
  const usableDomain=domain&&!/(gmail|googlemail|yahoo|outlook|hotmail|icloud|me|mac|aol|protonmail)\./i.test(domain)?domain:'';
  const website=String(contact.website||contact.raw?.website||profile.website||profile.metadata?.website||'').replace(/^https?:\/\//i,'').replace(/^www\./i,'').replace(/\/.*$/,'').trim();
  return [
    email || '',
    email ? `"${email}"` : '',
    name&&usableDomain ? `"${name}" ${usableDomain}` : '',
    name&&organization ? `"${name}" "${organization}"` : '',
    name&&website ? `"${name}" ${website}` : '',
    name ? `"${name}" LinkedIn` : ''
  ].map(value=>String(value||'').replace(/\s+/g,' ').trim()).filter(Boolean).filter((value,index,array)=>array.indexOf(value)===index);
}

function normalizeOutscraperSearchResult(row={}){
  const url=String(row.link||row.url||row.href||row.source_url||row.displayed_link||'').trim();
  const rawTitle=String(row.title||row.name||row.heading||'').trim();
  const snippet=dashboardShortText(meetingPrepPublicEvidenceText(row.snippet||row.description||row.text||row.content||row.summary||''), '', 520);
  if(!rawTitle&&!snippet&&!url)return null;
  const title=dashboardShortText(rawTitle||url,'Search result',180);
  return {
    title,
    url,
    displayedLink:String(row.displayed_link||row.displayedLink||'').trim(),
    snippet
  };
}
function meetingPrepPublicEvidenceText(value=''){
  return String(value||'')
    .replace(/\bAge\s+\d{1,3}\b/gi,'')
    .replace(/(?:\+?1[\s.-]?)?\(?\d{3}\)?[\s.-]?\d{3}[\s.-]?\d{4}/g,'')
    .replace(/\s+/g,' ')
    .trim();
}
function meetingPrepRejectedPublicResult(result={}){
  const text=[result.title,result.url,result.displayedLink].filter(Boolean).join(' ').toLowerCase();
  return /\b(truepeoplesearch|whitepages|beenverified|spokeo|mylife|intelius|peoplefinders|radaris|usphonebook|fastpeoplesearch|clustrmaps|truthfinder)\b/i.test(text);
}

function flattenOutscraperSearchResults(data={}){
  const rows=(Array.isArray(data.data)?data.data:[data]).flat(5).filter(Boolean);
  const candidates=[];
  for(const row of rows){
    if(!row||typeof row!=='object')continue;
    const nested=[
      row.organic_results,
      row.organicResults,
      row.results,
      row.items,
      row.serp_results,
      row.search_results
    ].filter(Boolean);
    if(nested.length){
      nested.flat(4).filter(Boolean).forEach(item=>candidates.push(item));
    }else{
      candidates.push(row);
    }
  }
  return candidates.map(normalizeOutscraperSearchResult).filter(Boolean).filter(result=>!meetingPrepRejectedPublicResult(result));
}

function meetingPrepSearchResultMatchesAttendee(result={}, attendee={}, contact={}, profile={}){
  const email=normalizeContextEmail(attendee.email||contact.email||relationshipProfilePrimaryEmail(profile)||'');
  const name=firstLookCandidateCleanName(attendee.name||contact.name||profile.displayName||profile.display_name||profile.name||'').toLowerCase();
  const domain=String(email.split('@')[1]||'').replace(/^www\./i,'').toLowerCase();
  const organization=firstLookCandidateCleanName(contact.company||contact.organization||profile.company||profile.organization||profile.metadata?.company||profile.metadata?.organization||'').toLowerCase();
  const text=[result.title,result.snippet,result.url,result.displayedLink].filter(Boolean).join(' ').toLowerCase();
  if(email&&text.includes(email))return true;
  if(name&&domain&&text.includes(name)&&text.includes(domain))return true;
  if(name&&organization&&text.includes(name)&&text.includes(organization))return true;
  if(name&&/linkedin\.com\/in\//i.test(result.url||'')&&text.includes(name))return true;
  return false;
}

function meetingPrepSearchResultScore(result={}, attendee={}, contact={}, profile={}){
  const email=normalizeContextEmail(attendee.email||contact.email||relationshipProfilePrimaryEmail(profile)||'');
  const name=firstLookCandidateCleanName(attendee.name||contact.name||profile.displayName||profile.display_name||profile.name||'').toLowerCase();
  const organization=firstLookCandidateCleanName(contact.company||contact.organization||profile.company||profile.organization||profile.metadata?.company||profile.metadata?.organization||'').toLowerCase();
  const text=[result.title,result.snippet,result.url,result.displayedLink].filter(Boolean).join(' ').toLowerCase();
  let score=0;
  if(/linkedin\.com\/in\//i.test(result.url||''))score+=120;
  if(/forbes|westwoodintl\.com|hopemakers|hci\.org|hrtechoutlook/i.test(result.url||''))score+=35;
  if(email&&text.includes(email))score+=30;
  if(name&&text.includes(name))score+=24;
  if(organization&&text.includes(organization))score+=20;
  if(/\b(pdf|download)\b/i.test(result.url||result.title||''))score-=12;
  return score;
}

function meetingPrepLinkedInKnownProfileUrl(attendee={}, contact={}, profile={}){
  return String(
    profile.linkedinUrl || profile.linkedin_url ||
    attendee.linkedinUrl || attendee.linkedin_url ||
    contact.linkedinUrl || contact.linkedin_url || contact.raw?.linkedinUrl ||
    extractLinkedInUrl(profile) || extractLinkedInUrl(contact) || ''
  ).trim();
}

function meetingPrepLinkedInActivityUrl(profileUrl=''){
  const clean=String(profileUrl||'').replace(/[#?].*$/,'').replace(/\/$/,'').trim();
  if(!clean)return '';
  if(/linkedin\.com\/in\//i.test(clean))return `${clean}/recent-activity/all/`;
  return clean;
}

function meetingPrepLinkedInRecentQueries(attendee={}, contact={}, profile={}){
  const name=firstLookCandidateCleanName(attendee.name||contact.name||profile.displayName||profile.display_name||profile.name||'');
  const organization=firstLookCandidateCleanName(contact.company||contact.organization||profile.company||profile.organization||profile.metadata?.company||profile.metadata?.organization||'');
  return [
    name&&organization ? `${name} LinkedIn ${organization}` : '',
    name ? `${name} LinkedIn posts` : '',
    name ? `site:linkedin.com/posts "${name}"` : '',
    name ? `site:linkedin.com/feed/update "${name}"` : '',
    name&&organization ? `site:linkedin.com/posts "${name}" "${organization}"` : ''
  ].map(value=>String(value||'').replace(/\s+/g,' ').trim()).filter(Boolean).filter((value,index,array)=>array.indexOf(value)===index);
}

function meetingPrepLinkedInSignalScore(result={}, attendee={}, contact={}, profile={}){
  const base=meetingPrepSearchResultScore(result,attendee,contact,profile);
  const url=String(result.url||'');
  let score=base;
  if(/linkedin\.com\/posts\//i.test(url))score+=140;
  if(/linkedin\.com\/feed\/update/i.test(url))score+=130;
  if(/linkedin\.com\/pulse\//i.test(url))score+=45;
  if(/linkedin\.com\/in\//i.test(url))score+=20;
  return score;
}

async function lookupMeetingPrepLinkedInRecentSignal(attendee={}, contact={}, profile={}){
  const knownProfileUrl=meetingPrepLinkedInKnownProfileUrl(attendee,contact,profile);
  const activityUrl=meetingPrepLinkedInActivityUrl(knownProfileUrl);
  if(activityUrl){
    const name=firstLookCandidateCleanName(attendee.name||contact.name||profile.displayName||profile.display_name||profile.name||'this attendee');
    const fallbackSummary=`LinkedIn activity link prepared for ${name}. Open LinkedIn activity: ${activityUrl}`;
    return {
      configured:!!OUTSCRAPER_API_KEY,
      status:'activity_link_prepared',
      query:'',
      title:`LinkedIn activity for ${name}`,
      url:activityUrl,
      summary:fallbackSummary,
      sourceRefs:[{
        type:'linkedin_activity_fallback',
        sourceType:'known_linkedin_profile_activity',
        sourceId:activityUrl,
        title:`LinkedIn activity for ${name}`,
        summary:fallbackSummary,
        confidence:'public_source'
      }],
      attempts:[],
      rawResultCount:0,
      completedAt:new Date().toISOString()
    };
  }
  const queries=meetingPrepLinkedInRecentQueries(attendee,contact,profile);
  const attempts=[];
  const selected=[];
  for(const query of queries.slice(0,1)){
    const search=await lookupOutscraperGoogleSearch(query).catch(e=>({configured:!!OUTSCRAPER_API_KEY,query,error:e.message,results:[]}));
    attempts.push({query,configured:search.configured,error:search.error||'',rawCount:search.rawCount||0});
    const matches=safeArray(search.results)
      .filter(result=>/linkedin\.com\/(posts|feed\/update|pulse|in)\//i.test(result.url||''))
      .filter(result=>meetingPrepSearchResultMatchesAttendee(result,attendee,contact,profile)||/linkedin\.com\/(posts|feed\/update)\//i.test(result.url||''));
    selected.push(...matches);
    if(selected.some(result=>/linkedin\.com\/(posts|feed\/update)\//i.test(result.url||'')))break;
  }
  const unique=selected.filter((result,index,array)=>{
    const key=String(result.url||result.title||result.snippet||'').toLowerCase();
    return key&&array.findIndex(item=>String(item.url||item.title||item.snippet||'').toLowerCase()===key)===index;
  }).sort((a,b)=>meetingPrepLinkedInSignalScore(b,attendee,contact,profile)-meetingPrepLinkedInSignalScore(a,attendee,contact,profile));
  const post=unique.find(result=>/linkedin\.com\/(posts|feed\/update)\//i.test(result.url||''))||null;
  const profileResult=unique.find(result=>/linkedin\.com\/in\//i.test(result.url||''))||null;
  const name=firstLookCandidateCleanName(attendee.name||contact.name||profile.displayName||profile.display_name||profile.name||'this attendee');
  if(post){
    const summary=dashboardShortText([post.title,post.snippet].filter(Boolean).join(': '),`VAL found a public LinkedIn post result for ${name}.`,700);
    return {
      configured:attempts.some(attempt=>attempt.configured),
      status:'post_found',
      query:attempts.map(attempt=>attempt.query).filter(Boolean).join(' | '),
      title:post.title,
      url:post.url,
      summary:`Latest public LinkedIn signal VAL found for ${name}: ${summary} Open post: ${post.url}`,
      sourceRefs:[{
        type:'linkedin_recent_signal',
        sourceType:'outscraper_google_linkedin_recent_signal',
        sourceId:post.url,
        title:post.title||`LinkedIn post for ${name}`,
        summary,
        confidence:'public_source'
      }],
      attempts,
      rawResultCount:attempts.reduce((total,attempt)=>total+Number(attempt.rawCount||0),0),
      completedAt:new Date().toISOString()
    };
  }
  const fallbackUrl=activityUrl||profileResult?.url||knownProfileUrl||'';
  const fallbackTitle=profileResult?.title||`LinkedIn activity for ${name}`;
  const fallbackSummary=fallbackUrl
    ? `No readable recent LinkedIn post was returned for ${name}. Open LinkedIn activity/profile: ${fallbackUrl}`
    : `No readable recent LinkedIn post was returned for ${name}, and VAL does not have a LinkedIn profile URL yet.`;
  return {
    configured:attempts.some(attempt=>attempt.configured)||!!OUTSCRAPER_API_KEY,
    status:fallbackUrl?'profile_fallback':'not_found',
    query:attempts.map(attempt=>attempt.query).filter(Boolean).join(' | '),
    title:fallbackTitle,
    url:fallbackUrl,
    summary:fallbackSummary,
    sourceRefs:fallbackUrl?[{
      type:'linkedin_activity_fallback',
      sourceType:'outscraper_google_linkedin_recent_signal',
      sourceId:fallbackUrl,
      title:fallbackTitle,
      summary:fallbackSummary,
      confidence:'public_source'
    }]:[],
    attempts,
    rawResultCount:attempts.reduce((total,attempt)=>total+Number(attempt.rawCount||0),0),
    completedAt:new Date().toISOString()
  };
}

async function lookupOutscraperGoogleSearch(query){
  const outscraperKey=await resolveIntegrationSecret('outscraper','api_key',OUTSCRAPER_API_KEY);
  if(!outscraperKey) return {configured:false, error:'OUTSCRAPER_API_KEY is not set'};
  const url=new URL(OUTSCRAPER_GOOGLE_SEARCH_URL);
  url.searchParams.set('query',query);
  url.searchParams.set('limit','10');
  url.searchParams.set('async','true');
  const response=await fetchWithTimeout(url.toString(),{headers:{'X-API-KEY':outscraperKey}},OUTSCRAPER_SUBMIT_TIMEOUT_MS,'Outscraper Google Search submit');
  const submittedData=await readJsonResponse(response);
  if(!response.ok)return {configured:true,query,error:submittedData.errorMessage||submittedData.message||`Outscraper ${response.status}`};
  let data=submittedData;
  const submittedStatus=String(submittedData.status||'').toLowerCase();
  if(submittedStatus==='pending'||!flattenOutscraperSearchResults(submittedData).length){
    const requestId=submittedData.id||submittedData.request_id;
    if(requestId){
      const polled=await pollOutscraperRequest(requestId,submittedData.results_location,outscraperKey);
      if(polled.ok)data=polled.data;
      else return {configured:true,query,error:polled.error||'Outscraper Google Search did not finish'};
    }
  }
  const results=flattenOutscraperSearchResults(data);
  return {configured:true,query,results,rawCount:results.length};
}

async function lookupMeetingPrepWebEvidence(attendee={}, contact={}, profile={}){
  const queries=meetingPrepPublicSearchQueries(attendee,contact,profile);
  if(!queries.length)return {configured:!!OUTSCRAPER_API_KEY,query:'',results:[],sourceRefs:[],summary:'',rawResultCount:0};
  const attempts=[];
  const selected=[];
  for(const query of queries.slice(0,4)){
    const search=await lookupOutscraperGoogleSearch(query).catch(e=>({configured:!!OUTSCRAPER_API_KEY,query,error:e.message,results:[]}));
    attempts.push({query,configured:search.configured,error:search.error||'',rawCount:search.rawCount||0});
    const matches=safeArray(search.results).filter(result=>meetingPrepSearchResultMatchesAttendee(result,attendee,contact,profile));
    selected.push(...matches);
    if(selected.length>=3)break;
  }
  const unique=selected.filter((result,index,array)=>{
    const key=String(result.url||result.title||result.snippet||'').toLowerCase();
    return key&&array.findIndex(item=>String(item.url||item.title||item.snippet||'').toLowerCase()===key)===index;
  }).sort((a,b)=>meetingPrepSearchResultScore(b,attendee,contact,profile)-meetingPrepSearchResultScore(a,attendee,contact,profile)).slice(0,5);
  const name=firstLookCandidateCleanName(attendee.name||contact.name||profile.displayName||profile.display_name||profile.name||'this attendee');
  const sourceRefs=unique.map((result,index)=>({
    type:'web_search_result',
    sourceType:'outscraper_google_search_result',
    sourceId:result.url||stableKey(`web:${name}:${index}`),
    title:result.title||`Web result for ${name}`,
    summary:dashboardShortText([result.title,result.snippet].filter(Boolean).join(': '),'Public web result found by Outscraper Google Search.',700),
    confidence:'public_source'
  }));
  const summary=sourceRefs.length
    ? `This is what VAL found on the web about ${name}: ${sourceRefs.map(ref=>ref.summary).filter(Boolean).slice(0,3).join(' ')}`
    : '';
  return {
    configured:attempts.some(attempt=>attempt.configured),
    query:attempts.map(attempt=>attempt.query).filter(Boolean).join(' | '),
    attempts,
    results:unique,
    sourceRefs,
    summary,
    rawResultCount:attempts.reduce((total,attempt)=>total+Number(attempt.rawCount||0),0),
    cacheStatus:'ran',
    completedAt:new Date().toISOString()
  };
}

app.post('/api/val/meeting-intel',async(req,res)=>{
  try{
    const event = req.body.event || req.body || {};
    const attendees = inferAttendeesFromEvent(event);
    const enriched = [];
    for(const attendee of attendees){
      const rocket = await lookupRocketReach(attendee).catch(e=>({configured:!!ROCKETREACH_API_KEY,error:e.message}));
      const profile = rocket.data || {};
      const outscraper = await lookupOutscraperLinkedIn(attendee,profile).catch(e=>({configured:!!OUTSCRAPER_API_KEY,error:e.message}));
      const linkedInRecentSignal = await lookupMeetingPrepLinkedInRecentSignal(attendee,{},profile).catch(e=>({configured:!!OUTSCRAPER_API_KEY,error:e.message,results:[]}));
      const webSearch = await lookupMeetingPrepWebEvidence(attendee,{},profile).catch(e=>({configured:!!OUTSCRAPER_API_KEY,error:e.message,results:[]}));
      enriched.push({attendee, rocketReach:rocket, outscraper, linkedInRecentSignal, webSearch});
    }
    res.json({ok:true, attendees:enriched, missingConfig:{
      rocketReach:!ROCKETREACH_API_KEY
    }, optionalConfig:{
      outscraperConfigured:!!OUTSCRAPER_API_KEY && !!OUTSCRAPER_LINKEDIN_POSTS_URL,
      outscraperGoogleSearchConfigured:!!OUTSCRAPER_API_KEY && !!OUTSCRAPER_GOOGLE_SEARCH_URL
    }});
  }catch(e){ res.status(500).json({error:e.message}); }
});

function deepgramModelName(value){
  return String(value||'').trim().replace(/[^a-zA-Z0-9_.:-]/g,'').slice(0,120);
}
function deepgramTtsModel(){
  return deepgramModelName(DEEPGRAM_TTS_MODEL)||'aura-2-cora-en';
}
function deepgramTtsModelSource(){
  if(process.env.DEEPGRAM_TTS_MODEL) return 'DEEPGRAM_TTS_MODEL';
  if(process.env.VAL_TTS_VOICE) return 'VAL_TTS_VOICE';
  if(process.env.DEEPGRAM_VOICE_MODEL) return 'DEEPGRAM_VOICE_MODEL';
  return 'default';
}
function deepgramKeySource(){
  if(process.env.DEEPGRAM_API_KEY) return 'DEEPGRAM_API_KEY';
  if(process.env.DG_KEY) return 'DG_KEY';
  return '';
}
let lastDeepgramTtsDiagnostic=null;
async function requestDeepgramTts(text){
  if(!DEEPGRAM_API_KEY){
    const err=new Error('Deepgram voice is not configured. Add DEEPGRAM_API_KEY in Railway.');
    err.statusCode=503;
    throw err;
  }
  const model=deepgramTtsModel();
  const controller=new AbortController();
  const timer=setTimeout(()=>controller.abort(),20000);
  let dg;
  try{
    dg=await fetch(`https://api.deepgram.com/v1/speak?model=${encodeURIComponent(model)}`,{method:'POST',headers:{'Authorization':`Token ${DEEPGRAM_API_KEY}`,'Content-Type':'application/json'},body:JSON.stringify({text}),signal:controller.signal});
  }finally{clearTimeout(timer);}
  const contentType=dg.headers.get('content-type')||'audio/mpeg';
  const buffer=Buffer.from(await dg.arrayBuffer());
  if(!dg.ok){
    let detail=buffer.toString('utf8').slice(0,500);
    try{const parsed=JSON.parse(detail);detail=parsed.err_msg||parsed.message||parsed.error||detail;}catch(_){}
    const err=new Error(`Deepgram TTS failed (${dg.status})`);
    err.statusCode=dg.status;
    err.detail=detail;
    throw err;
  }
  return {buffer,contentType,model};
}
app.get('/api/val/voice/status',(req,res)=>{
  res.json({ok:true,provider:'deepgram',ttsConfigured:!!DEEPGRAM_API_KEY,ttsKeySource:deepgramKeySource(),ttsModel:deepgramTtsModel(),ttsModelSource:deepgramTtsModelSource(),voiceResponseTemperature:VAL_VOICE_RESPONSE_TEMPERATURE,sttModel:DEEPGRAM_STT_MODEL,sttEndpointingMs:DEEPGRAM_STT_ENDPOINTING_MS,ttsProxy:true,lastTtsDiagnostic:lastDeepgramTtsDiagnostic});
});
app.post('/api/val/voice/test',async(req,res)=>{
  const text=String(req.body?.text||'This is the Deepgram voice VAL will use.').replace(/\s+/g,' ').trim().slice(0,500);
  const started=Date.now();
  try{
    const result=await requestDeepgramTts(text||'This is the Deepgram voice VAL will use.');
    lastDeepgramTtsDiagnostic={ok:true,checkedAt:new Date().toISOString(),provider:'deepgram',model:result.model,modelSource:deepgramTtsModelSource(),keySource:deepgramKeySource(),contentType:result.contentType,bytes:result.buffer.length,latencyMs:Date.now()-started};
    res.json(lastDeepgramTtsDiagnostic);
  }catch(e){
    const aborted=e.name==='AbortError';
    lastDeepgramTtsDiagnostic={ok:false,checkedAt:new Date().toISOString(),provider:'deepgram',model:deepgramTtsModel(),modelSource:deepgramTtsModelSource(),keySource:deepgramKeySource(),statusCode:e.statusCode||(aborted?504:500),error:aborted?'Deepgram TTS timed out.':e.message,detail:e.detail||''};
    console.warn('[voice] Deepgram voice test failed',lastDeepgramTtsDiagnostic.statusCode,lastDeepgramTtsDiagnostic.detail||lastDeepgramTtsDiagnostic.error);
    res.status(lastDeepgramTtsDiagnostic.statusCode).json(lastDeepgramTtsDiagnostic);
  }
});
app.post('/api/val/tts',async(req,res)=>{
  try{
    const text=String(req.body?.text||'').replace(/\s+/g,' ').trim().slice(0,4000);
    if(!text) return res.status(400).json({ok:false,error:'No text supplied for voice playback.'});
    const result=await requestDeepgramTts(text);
    lastDeepgramTtsDiagnostic={ok:true,checkedAt:new Date().toISOString(),provider:'deepgram',model:result.model,modelSource:deepgramTtsModelSource(),keySource:deepgramKeySource(),contentType:result.contentType,bytes:result.buffer.length};
    res.set({'Content-Type':result.contentType.includes('audio/')?result.contentType:'audio/mpeg','Cache-Control':'no-store, max-age=0','X-VAL-TTS-Provider':'deepgram','X-VAL-TTS-Model':result.model});
    res.send(result.buffer);
  }catch(e){
    const aborted=e.name==='AbortError';
    const status=e.statusCode||(aborted?504:500);
    lastDeepgramTtsDiagnostic={ok:false,checkedAt:new Date().toISOString(),provider:'deepgram',model:deepgramTtsModel(),modelSource:deepgramTtsModelSource(),keySource:deepgramKeySource(),statusCode:status,error:aborted?'Deepgram TTS timed out.':e.message,detail:e.detail||''};
    console.warn('[voice] TTS proxy failed',status,lastDeepgramTtsDiagnostic.detail||lastDeepgramTtsDiagnostic.error);
    res.status(status).json({ok:false,error:lastDeepgramTtsDiagnostic.error,detail:lastDeepgramTtsDiagnostic.detail,model:lastDeepgramTtsDiagnostic.model,modelSource:lastDeepgramTtsDiagnostic.modelSource,keySource:lastDeepgramTtsDiagnostic.keySource});
  }
});

