async function applyValFirstLookCandidates(run={}){
  const candidates=(await listValFirstLookCandidates(run.id)).filter(candidate=>['kept','corrected'].includes(candidate.decision));
  if(!candidates.length)throw new Error('Keep at least one relationship or project before delivering the proposed map.');
  for(const candidate of candidates){
    const payload=candidate.payload||{};
    const kind=candidate.type==='relationship'?(payload.kind||'person'):'project';
    const hasWitnessingEvidence=(candidate.sourceEvidence||[]).some(item=>item.source==='witnessing')||Array.isArray(payload.witnessingEvidence)&&payload.witnessingEvidence.length>0;
    if(!firstLookCandidateIdentityLooksSafe(payload.proposedName||'',kind,{allowSingleWordPerson:hasWitnessingEvidence&&kind==='person'}))throw new Error('Every kept proposal needs a clear person, organization, or project name before it can be delivered.');
    if(!Array.isArray(candidate.sourceEvidence)||!candidate.sourceEvidence.length)throw new Error('Every kept proposal needs source evidence before it can be delivered.');
    if(payload.admission?.accepted!==true)throw new Error('Resolve the identity evidence for every kept proposal before it can be delivered.');
  }
  const changeSetId=uuid('flcs');
  const now=new Date().toISOString();
  const relationshipCandidates=candidates.filter(candidate=>candidate.type==='relationship');
  const projectCandidates=candidates.filter(candidate=>candidate.type==='project');
  const buildResult=async(upsert,linkOwner)=>{
    const relationshipProfilesByName=new Map();
    const deliveredRelationships=[];
    const deliveredProjects=[];
    const relationshipLinks=[];
    for(const candidate of relationshipCandidates){
      const profile=await upsert(firstLookDeliveryRow(firstLookDeliveryProfileCandidate(candidate,relationshipProfilesByName)));
      relationshipProfilesByName.set(firstLookCandidateCleanName(candidate.payload?.proposedName||'').toLowerCase(),publicRelationshipProfile(profile));
      deliveredRelationships.push({candidateId:candidate.id,id:profile.id,name:profile.displayName,profileKey:profile.profileKey||profile.profile_key||''});
    }
    for(const candidate of projectCandidates){
      const profile=await upsert(firstLookDeliveryRow(firstLookDeliveryProfileCandidate(candidate,relationshipProfilesByName)));
      const ownerName=firstLookCandidateCleanName(candidate.payload?.ownerRelationshipName||'').toLowerCase();
      const owner=ownerName?relationshipProfilesByName.get(ownerName)||null:null;
      if(owner){
        const projectId=profile.projectId||profile.project_id||profile.profileKey||profile.profile_key||profile.id;
        const link=await linkOwner({
          projectId,
          projectName:profile.displayName||profile.display_name||candidate.payload?.proposedName||'',
          relationshipId:owner.id||owner.personId||owner.profileKey||'',
          relationshipName:owner.displayName||candidate.payload?.ownerRelationshipName||'',
          candidateId:candidate.id
        });
        if(link)relationshipLinks.push(link);
      }
      deliveredProjects.push({candidateId:candidate.id,id:profile.id,name:profile.displayName,projectId:profile.projectId||profile.project_id||'',profileKey:profile.profileKey||profile.profile_key||''});
    }
    return {relationships:deliveredRelationships,projects:deliveredProjects,relationshipLinks,noExternalAction:true};
  };
  let result;
  await valDbReady;
  if(pgPool){
    const client=await pgPool.connect();
    try{
      await client.query('BEGIN');
      result=await buildResult(
        row=>firstLookDeliveryUpsertProfile(client,row),
        async link=>{
          const id=uuid('evlink');
          await client.query(`insert into val_evidence_links (id,tenant_id,user_id,source_type,source_id,source_label,target_type,target_id,relationship,summary,quote,confidence,metadata,created_at)
            values ($1,$2,$3,'relationship_profile',$4,$5,'project_profile',$6,'linked_to_project',$7,'',$8,$9,now())`,[
            id,tenantId(),currentUserId(),link.relationshipId,link.relationshipName,link.projectId,
            link.relationshipName+' is linked to '+link.projectName+' from an approved First Look packet.',0.8,
            JSON.stringify({source:'val_first_look_delivery',candidateId:link.candidateId,projectName:link.projectName,relationshipName:link.relationshipName,noExternalAction:true})
          ]);
          return {id,projectId:link.projectId,relationshipId:link.relationshipId};
        }
      );
      await client.query(`update val_first_look_candidates set decision='delivered',delivered_at=$1::timestamptz,updated_at=$1::timestamptz
        where tenant_id=$2 and user_id=$3 and run_id=$4 and id = any($5::text[])`,[now,tenantId(),currentUserId(),run.id,candidates.map(candidate=>candidate.id)]);
      await client.query(`insert into val_first_look_change_sets (id,run_id,tenant_id,user_id,status,candidate_ids_json,result_json,created_at,applied_at)
        values ($1,$2,$3,$4,'applied',$5,$6,$7::timestamptz,$7::timestamptz)`,[changeSetId,run.id,tenantId(),currentUserId(),JSON.stringify(candidates.map(candidate=>candidate.id)),JSON.stringify(result),now]);
      await client.query('COMMIT');
    }catch(error){
      await client.query('ROLLBACK').catch(()=>{});
      throw error;
    }finally{client.release();}
  }else{
    const store=valStore();
    const profiles=transcriptFileArray(store,'relationshipProfiles');
    const upsert=async row=>{
      const index=profiles.findIndex(item=>item.tenantId===row.tenantId&&item.profileType===row.profileType&&item.profileKey===row.profileKey);
      if(index>=0){
        profiles[index]={...profiles[index],...row,id:profiles[index].id,createdAt:profiles[index].createdAt||row.createdAt,metadataJson:{...evidenceJsonValue(profiles[index].metadataJson||profiles[index].metadata,{}),...row.metadataJson}};
        return profiles[index];
      }
      profiles.push(row);
      return row;
    };
    result=await buildResult(upsert,async link=>{
      const row={
        id:uuid('evlink'),tenantId:tenantId(),userId:currentUserId(),sourceType:'relationship_profile',sourceId:link.relationshipId,
        sourceLabel:link.relationshipName,targetType:'project_profile',targetId:link.projectId,relationship:'linked_to_project',
        summary:link.relationshipName+' is linked to '+link.projectName+' from an approved First Look packet.',quote:'',confidence:0.8,
        metadata:{source:'val_first_look_delivery',candidateId:link.candidateId,projectName:link.projectName,relationshipName:link.relationshipName,noExternalAction:true},createdAt:now
      };
      transcriptFileArray(store,'evidenceLinks').push(row);
      return {id:row.id,projectId:link.projectId,relationshipId:link.relationshipId};
    });
    const candidateRows=store.valFirstLookCandidates||[];
    for(const candidate of candidates){
      const index=candidateRows.findIndex(item=>item.tenantId===tenantId()&&item.userId===currentUserId()&&item.runId===run.id&&item.id===candidate.id);
      if(index>=0)candidateRows[index]={...candidateRows[index],decision:'delivered',deliveredAt:now,updatedAt:now};
    }
    store.valFirstLookChangeSets.push({id:changeSetId,runId:run.id,tenantId:tenantId(),userId:currentUserId(),status:'applied',candidateIds:candidates.map(candidate=>candidate.id),result,createdAt:now,appliedAt:now});
    saveValStore(store);
  }
  await auditLog({action:'val_first_look_candidates_delivered',resourceType:'val_first_look',resourceId:run.id,metadata:{changeSetId,relationshipCount:result.relationships.length,projectCount:result.projects.length},success:true}).catch(()=>{});
  return {id:changeSetId,runId:run.id,status:'applied',candidateIds:candidates.map(candidate=>candidate.id),result,appliedAt:now};
}
async function readGoogleDoc({documentId,query}){
  const token=await googleDocsToken();
  let id=googleDocIdFromInput(documentId||query||'');
  let match=null, matches=[];
  if(!id){
    matches=await searchGoogleDocs(query||'',8);
    match=matches[0]||null;
    id=match?.id||'';
  }
  if(!id) throw new Error('No matching Google Doc found. Try the exact document title or paste the Google Doc URL.');
  let doc;
  try{
    doc=await googleApiJson(googleDocsGetUrl(id),{headers:{Authorization:`Bearer ${token}`}});
    doc=await googleDocWithExportFallback(id,doc,doc.title||match?.name||'Google Doc');
  }catch(e){
    if(!googleApiIsDocsDisabled(e)) throw e;
    const html=await googleDriveExportText(id,'text/html');
    doc=googleDocFromExportedHtml(html,match?.name||'Google Doc');
  }
  const text=googleDocExtractedText(doc);
  return {id,title:doc.title||match?.name||'Google Doc',url:googleDocUrl(id),text,match,otherMatches:matches.slice(1,5)};
}
async function googleDocsContextForQuery(query){
  if(!/\b(read|review|open|find|pull up|look at|chapter|manuscript|memoir|document|doc|google doc|drive)\b/i.test(String(query||''))) return '';
  try{
    const doc=await readGoogleDoc({query});
    if(!doc.text) return `Google Doc found but no readable text was returned.\nTitle: ${doc.title}\nURL: ${doc.url}`;
    await saveMemoryItem({kind:'google_doc_read',summary:`Read Google Doc: ${doc.title}`,rawText:doc.text.slice(0,12000),importance:4,metadata:{source:'google_docs',documentId:doc.id,url:doc.url,title:doc.title}});
    return [
      `Google Doc source found for the user's request.`,
      `Title: ${doc.title}`,
      `URL: ${doc.url}`,
      doc.otherMatches?.length?`Other possible matches: ${doc.otherMatches.map(f=>f.name).join(', ')}`:'',
      `Document text:\n${doc.text.slice(0,45000)}`
    ].filter(Boolean).join('\n\n');
  }catch(e){
    if(/auth|required|scope|reconnect/i.test(e.message)) return `Google Docs are not readable yet: ${e.message}. Tell the user to reconnect Google from Integration Status and approve Drive/Docs permissions.`;
    return `Google Docs lookup did not find a readable matching document: ${e.message}`;
  }
}
function isGoogleDocRewriteRequest(query){
  const text=String(query||'').toLowerCase();
  return /\b(rewrite|revise|redraft|rework|polish|line edit|developmental edit|edit)\b/.test(text)
    && /\b(chapter|manuscript|memoir|book|google doc|document|doc|draft)\b/.test(text);
}
function isWholeDocumentRewriteRequest(query){
  return /\b(entire|whole|full|all of|complete)\b/i.test(String(query||''))
    && /\b(document|doc|google doc|manuscript|memoir|book|draft)\b/i.test(String(query||''));
}
function googleDocRewriteTitle(sourceTitle,query,scope){
  const chapter=String(query||'').match(/\bchapter\s*(\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve)\b/i);
  const label=scope==='chapter'&&chapter?`Chapter ${chapter[1]} Rewrite`:'Full Document Rewrite';
  const base=String(sourceTitle||label).replace(/\s+/g,' ').trim();
  return `${label} - ${base} - ${new Date().toISOString().slice(0,10)}`;
}
function splitChapterText(text,maxChars=18000){
  const clean=String(text||'').replace(/\r\n/g,'\n').trim();
  if(clean.length<=maxChars) return clean?[clean]:[];
  const paras=clean.split(/\n{2,}/);
  const chunks=[];
  let current='';
  for(const para of paras){
    const next=current ? current+'\n\n'+para : para;
    if(next.length<=maxChars){current=next;continue;}
    if(current){chunks.push(current);current='';}
    if(para.length<=maxChars){current=para;continue;}
    for(let i=0;i<para.length;i+=maxChars) chunks.push(para.slice(i,i+maxChars));
  }
  if(current) chunks.push(current);
  return chunks;
}
const CHAPTER_WORD_NUMBERS = {one:1,two:2,three:3,four:4,five:5,six:6,seven:7,eight:8,nine:9,ten:10,eleven:11,twelve:12,thirteen:13,fourteen:14,fifteen:15,sixteen:16,seventeen:17,eighteen:18,nineteen:19,twenty:20};
function requestedChapterNumber(query){
  const m=String(query||'').match(/\bchapter\s*(\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty)\b/i);
  if(!m) return null;
  const raw=m[1].toLowerCase();
  return /^\d+$/.test(raw)?Number(raw):CHAPTER_WORD_NUMBERS[raw]||null;
}
function extractRequestedChapterText(fullText,query){
  const chapter=requestedChapterNumber(query);
  const text=String(fullText||'').replace(/\r\n/g,'\n');
  if(!chapter||!text) return '';
  const word=Object.entries(CHAPTER_WORD_NUMBERS).find(([,n])=>n===chapter)?.[0]||'';
  const headingRe=new RegExp(`^\\s*(chapter\\s+(${chapter}${word?'|'+word:''})\\b[^\\n]*|${chapter}[\\.)\\:-]\\s+[^\\n]{0,120})\\s*$`,'im');
  const start=text.search(headingRe);
  if(start<0) return '';
  const rest=text.slice(start);
  const nextRe=/^\s*(chapter\s+(\d+|one|two|three|four|five|six|seven|eight|nine|ten|eleven|twelve|thirteen|fourteen|fifteen|sixteen|seventeen|eighteen|nineteen|twenty)\b[^\n]*|\d+[\.)\:-]\s+[^\n]{0,120})\s*$/gim;
  let next=-1, match;
  while((match=nextRe.exec(rest))){
    if(match.index===0) continue;
    const raw=String(match[2]||match[1].match(/^\s*(\d+)/)?.[1]||'').toLowerCase();
    const n=/^\d+$/.test(raw)?Number(raw):CHAPTER_WORD_NUMBERS[raw]||null;
    if(!n||n>chapter){next=match.index;break;}
  }
  return (next>0?rest.slice(0,next):rest).trim();
}
function nestedRecordMetadata(record={}){
  const meta=record.metadata||{};
  return {...meta,...(meta.metadata||{})};
}
function valUploadedSourceTitle(record={}){
  const meta=nestedRecordMetadata(record);
  return meta.chapterTitle||meta.fileName||record.title||record.summary||'Uploaded VAL document';
}
function scoreValRewriteSource(record,query){
  const meta=nestedRecordMetadata(record);
  const text=String(record.rawText||record.raw_text||'').trim();
  if(text.length<400) return 0;
  const q=String(query||'').toLowerCase();
  const hay=[record.type,record.kind,record.title,record.summary,meta.fileName,meta.docType,meta.project,meta.projectType,meta.source,meta.chapterTitle,CLIENT_CONFIG.projectName,CLIENT_CONFIG.brandName].join(' ').toLowerCase();
  let score=0;
  if(/\bknowledge_document|processed_transcript|transcript\b/.test(String(record.type||record.kind||''))) score+=2;
  if(String(meta.source||'')==='val_file_upload') score+=7;
  if(/\b(manuscript|memoir|book|chapter|draft|knowledge_document)\b/.test(hay)) score+=5;
  if(isBookEditorProject()) score+=3;
  if(CLIENT_CONFIG.projectName&&hay.includes(String(CLIENT_CONFIG.projectName).toLowerCase())) score+=4;
  if(CLIENT_CONFIG.brandName&&hay.includes(String(CLIENT_CONFIG.brandName).toLowerCase())) score+=4;
  const chapter=requestedChapterNumber(query);
  if(chapter&&String(meta.chapterNumber||'')===String(chapter)) score+=8;
  if(chapter&&new RegExp(`\\bchapter\\s*${chapter}\\b`,'i').test(hay)) score+=5;
  if(isWholeDocumentRewriteRequest(query)&&/\b(manuscript|memoir|book)\b/.test(hay)) score+=7;
  if(isWholeDocumentRewriteRequest(query)&&text.length>12000) score+=Math.min(8,Math.floor(text.length/12000));
  const quoted=String(query||'').match(/["“]([^"”]{3,120})["”]/);
  if(quoted&&hay.includes(quoted[1].toLowerCase())) score+=10;
  const cleaned=q.replace(/\b(can you|please|could you|rewrite|revise|redraft|rework|polish|line edit|developmental edit|edit|entire|whole|full|all of|complete|the|my|our|doc|docs|document|google|drive|chapter|manuscript|memoir|book|draft)\b/g,' ').replace(/[^a-z0-9\s_-]/g,' ').replace(/\s+/g,' ').trim();
  if(cleaned.length>=3&&hay.includes(cleaned)) score+=6;
  return score;
}
async function readValUploadedRewriteSource({query,documentId}={}){
  if(documentId) return null;
  const [transcripts,memory]=await Promise.all([
    recentTranscripts(3650).catch(()=>[]),
    recentMemoryItems(3650,1000).catch(()=>[])
  ]);
  const fullRecords=(transcripts||[]).map(r=>({...r,sourceKind:'val_transcript'}));
  const chunkGroups=new Map();
  for(const item of memory||[]){
    const meta=nestedRecordMetadata(item);
    const transcriptId=meta.transcriptId||'';
    if(!transcriptId||!meta.chunkCount) continue;
    const existing=chunkGroups.get(transcriptId)||{...item,rawText:'',chunks:[],sourceKind:'val_memory_chunks'};
    existing.chunks.push(item);
    chunkGroups.set(transcriptId,existing);
  }
  const reconstructed=[...chunkGroups.values()].map(group=>{
    const chunks=group.chunks.sort((a,b)=>Number(nestedRecordMetadata(a).chunkIndex||0)-Number(nestedRecordMetadata(b).chunkIndex||0));
    return {...group,rawText:chunks.map(c=>c.rawText||c.raw_text||'').join('\n\n'),summary:chunks[0]?.summary||group.summary,metadata:chunks[0]?.metadata||group.metadata};
  });
  const candidates=[...fullRecords,...reconstructed]
    .map(record=>({record,score:scoreValRewriteSource(record,query)}))
    .filter(x=>x.score>0)
    .sort((a,b)=>b.score-a.score || String(b.record.rawText||'').length-String(a.record.rawText||'').length);
  const best=candidates[0]?.record;
  if(!best) return null;
  const text=String(best.rawText||best.raw_text||'').trim();
  return {id:best.id||'',title:valUploadedSourceTitle(best),url:'VAL uploaded file',text,source:'val_upload',record:best};
}
async function uploadedValDocumentContextForQuery(query){
  if(!/\b(read|review|open|find|pull up|look at|chapter|manuscript|memoir|document|doc|book|draft)\b/i.test(String(query||''))) return '';
  const doc=await readValUploadedRewriteSource({query}).catch(()=>null);
  if(!doc||!doc.text) return '';
  const requestedChapterText=extractRequestedChapterText(doc.text,query);
  const sourceText=requestedChapterText||doc.text;
  const scope=requestedChapterText?'requested chapter':'uploaded document';
  return [
    `Uploaded VAL ${scope} source found.`,
    `Title: ${doc.title}`,
    `Source: VAL memory upload`,
    `Readable characters available: ${doc.text.length}`,
    requestedChapterText?`Using extracted chapter characters: ${requestedChapterText.length}`:'',
    `Source text excerpt:\n${sourceText.slice(0,55000)}`
  ].filter(Boolean).join('\n\n');
}
function linkedDocumentReviewRequested(query=''){
  const text=String(query||'');
  return /\b(read|review|open|analy[sz]e|assess|examine|compare|look at|summari[sz]e)\b/i.test(text)
    && /\b(document|file|attachment|agreement|contract|mou|memorandum|scope|proposal|deck)\b/i.test(text);
}
function linkedDocumentQueryTerms(query='',projectContext=null){
  const stop=new Set(['about','after','again','also','and','are','can','could','document','documents','file','files','for','from','have','into','look','mou','our','please','read','review','that','the','this','with','would','you','your']);
  const text=[query,projectContext?.projectName||'',projectContext?.projectId||''].join(' ').toLowerCase();
  return [...new Set((text.match(/[a-z0-9]{3,}/g)||[]).filter(term=>!stop.has(term)))].slice(0,16);
}
function linkedDocumentScore(document={},query='',projectContext=null){
  const title=String(document.title||'').toLowerCase();
  const summary=String(document.summary||document.bodyPreview||'').toLowerCase();
  const project=String(document.project||'').toLowerCase();
  const source=[title,summary,project].join(' ');
  let score=String(document.sourceType||'').toLowerCase()==='email_attachment' ? 20 : 0;
  if(/\b(mou|memorandum|agreement|contract|scope|proposal)\b/i.test(query) && /\b(mou|memorandum|agreement|contract|scope|proposal)\b/.test(title)) score+=18;
  for(const term of linkedDocumentQueryTerms(query,projectContext)){
    if(title.includes(term)) score+=8;
    else if(source.includes(term)) score+=2;
  }
  const requestedTitle=String(query||'').match(/["“]([^"”]{3,120})["”]/)?.[1]?.toLowerCase();
  if(requestedTitle&&title.includes(requestedTitle)) score+=24;
  return score;
}
async function linkedGmailAttachmentContextForQuery(query='',projectContext=null){
  if(!linkedDocumentReviewRequested(query)) return '';
  const result=await valDocuments.list({limit:180});
  const candidates=(result.documents||[])
    .filter(document=>String(document.sourceType||'').toLowerCase()==='email_attachment')
    .map(document=>({document,score:linkedDocumentScore(document,query,projectContext)}))
    .filter(candidate=>candidate.score>20)
    .sort((a,b)=>b.score-a.score || String(b.document.createdAt||'').localeCompare(String(a.document.createdAt||'')));
  const selected=candidates[0]?.document;
  if(!selected) return '';
  const raw=selected.raw&&typeof selected.raw==='object' ? selected.raw : {};
  const messageId=String(selected.sourceId||raw.messageId||raw.message_id||'').trim();
  const attachmentId=String(raw.attachmentId||raw.attachment_id||'').trim();
  if(!messageId||!attachmentId) return '';
  const payload=await gmailFetchJson(
    `https://www.googleapis.com/gmail/v1/users/me/messages/${encodeURIComponent(messageId)}/attachments/${encodeURIComponent(attachmentId)}`,
    {},
    'Gmail document attachment'
  );
  if(!payload?.data) return '';
  const text=(await extractUploadedText({
    originalname:selected.title||'email-attachment',
    mimetype:selected.type||raw.mimeType||raw.contentType||'',
    buffer:Buffer.from(payload.data,'base64url')
  })).trim();
  if(!text) return '';
  return [
    'Linked VAL attachment source found.',
    `Title: ${selected.title}`,
    'Source: Gmail attachment linked in VAL',
    `Readable characters available: ${text.length}`,
    `Source text excerpt:\n${text.slice(0,55000)}`
  ].join('\n\n');
}
