    clientSummary:'',
    internalNotes:notes,
    keyDecisions:lines.filter(line=>/\b(decided|agreed|approved|selected|chose)\b/i.test(line)).slice(0,10),
    openQuestions:lines.filter(line=>/\?$/.test(line)).slice(0,10),
