async function loadTranscriptForCowork(transcriptId=''){
  const id=String(transcriptId || '').trim();
  if(!id) return null;
  const data=await transcriptIndexData(id);
  let transcript=data.transcripts[0] ? transcriptDetailFromIndex(data,data.transcripts[0]) : null;
  if(!transcript){
    const record=(await transcriptArchiveRecords(3650,1000)).find((item)=>String(item.id)===id);
    if(record){
      transcript=cleanTranscriptForUi(transcriptUiRecord(record,{includeText:true}));
      transcript.sourceReceipt=transcriptSourceReceipt(transcript);
    }
  }
  if(!transcript) return null;
  transcript.sourceReceipt=transcript.sourceReceipt || transcriptSourceReceipt(transcript);
  transcript.calendarEvent=await transcriptCalendarEventForOverview(transcript).catch(()=>({}));
  transcript.drafts=(await listDrafts()).filter((draft)=>String(draft.sourceContext?.transcriptId || '')===id);
  return transcript;
}
async function prepareCoworkTranscriptMeetingOverview({transcriptId}={}){
  const transcript=await loadTranscriptForCowork(transcriptId);
  if(!transcript) throw new Error('VAL could not load the selected transcript. It did not substitute another meeting.');
  return prepareTranscriptMeetingOverviewDraft(transcript,transcript.sourceReceipt?.actionItems || []);
}
async function createCoworkTranscriptActionItem({transcriptId,actionItemIndex,actionItem,sessionId='',workItemId=''}={}){
  const transcript=await loadTranscriptForCowork(transcriptId);
  if(!transcript) throw new Error('VAL could not load the selected transcript. It did not substitute another meeting.');
  const sourceItems=Array.isArray(transcript.sourceReceipt?.actionItems) ? transcript.sourceReceipt.actionItems.map((item)=>String(item||'').trim()).filter(Boolean) : [];
  const index=Number(actionItemIndex);
  const exactActionItem=Number.isInteger(index) && index >= 0 ? sourceItems[index] : '';
  if(!exactActionItem || String(actionItem||'').trim() !== exactActionItem) throw new Error('That Action Item no longer matches the selected Krisp receipt. Nothing was created.');
  const existing=(await transcriptIndexData(transcript.id)).tasks.find((task)=>String(task.sourceQuote||'').trim()===exactActionItem && String(task.status||'').toLowerCase()==='created');
  if(existing) return {task:{id:existing.taskId || '',title:exactActionItem,sourceQuote:exactActionItem},alreadyCreated:true,noExternalAction:true};
  const staged={
    taskId:uuid('tr_task'),
    transcriptId:transcript.id,
    assignedToContactId:'',
    assignedToName:'',
    taskTitle:exactActionItem,
    taskDescription:'',
    dueDate:null,
    priority:'medium',
    confidence:1,
    status:'staged',
    needsApproval:false,
    sourceQuote:exactActionItem,
    calendarEventId:transcript.meetingId || '',
    calendarEventTitle:transcript.title || transcript.meetingTitle || '',
    preserveSourceTitle:true,
    createdAt:new Date().toISOString()
  };
  await saveStagedTranscriptTask(staged);
  const task=await promoteTranscriptTask(staged);
  return {task,alreadyCreated:false,noExternalAction:true};
}
async function loadEmailThreadForCowork({messageId='',threadId='',conversationId='',provider=''}={}){
  const result=await valExecutiveInbox.draftBrief({messageId,threadId,conversationId,provider});
  const context=result?.context || {};
  const current=context.current_message || context.currentMessage || {};
  const selectedMessageId=String(current.messageId || current.id || messageId || '').trim();
  if(!selectedMessageId) return null;
  const selectedThreadId=String(context.threadId || current.threadId || threadId || '').trim();
  const selectedConversationId=String(context.conversationId || current.unifiedConversationId || conversationId || '').trim();
  const selectedProvider=String(context.provider || current.provider || provider || '').trim();
  const messages=await valConversationIdentity.messagesForConversation({
    conversationId:selectedConversationId,
    provider:selectedProvider,
    threadId:selectedThreadId,
    messageId:selectedMessageId
  });
  if(!messages.length) return null;
  const richMessages=await mapWithConcurrency(messages,4,async(message)=>{
    if((message.bodyHtml||message.body_html)||String(message.provider||selectedProvider||'').toLowerCase()!=='gmail'||!message.messageId)return message;
    try{
      const fresh=normalizeGmailMessage(await gmailFetchJson(
        `https://www.googleapis.com/gmail/v1/users/me/messages/${encodeURIComponent(message.messageId)}?format=full`,
        {},
        'Gmail thread message body'
      ));
      return {
        ...message,
        bodyPreview:fresh.bodyPreview||message.bodyPreview,
        bodyText:fresh.bodyText||message.bodyText,
        bodyHtml:fresh.bodyHtml||message.bodyHtml||'',
        attachments:fresh.attachments?.length ? fresh.attachments : message.attachments,
        raw:{...(message.raw||{}),...fresh}
      };
    }catch(e){
      return message;
    }
  });
  const drafts=await listDrafts();
  const existingDraft=drafts.find((draft)=>{
    const source=draft.sourceContext || {};
    if(String(source.source || '') !== 'executive_inbox_review_only') return false;
    const sameMessage=selectedMessageId && String(source.currentMessageId || source.current_message_id || '')===selectedMessageId;
    const sameConversation=selectedConversationId && String(source.conversationId || source.conversation_id || '')===selectedConversationId;
    const sameThread=selectedThreadId && String(source.threadId || source.thread_id || '')===selectedThreadId;
    return sameMessage || sameConversation || sameThread;
  }) || null;
  const linkedContexts=[
    ...(selectedMessageId ? await listEvidenceLinks({sourceType:'email_message',sourceId:selectedMessageId,limit:20}).catch(()=>[]) : []),
    ...(selectedThreadId ? await listEvidenceLinks({sourceType:'email_thread',sourceId:selectedThreadId,limit:20}).catch(()=>[]) : []),
    ...(selectedConversationId ? await listEvidenceLinks({sourceType:'email_thread',sourceId:selectedConversationId,limit:20}).catch(()=>[]) : [])
  ].filter((link,index,rows)=>link?.id && rows.findIndex(row=>row.id===link.id)===index);
  return {
    provider:selectedProvider || 'email',
    messageId:selectedMessageId,
    threadId:selectedThreadId,
    conversationId:selectedConversationId,
    subject:current.subject || richMessages[richMessages.length-1]?.subject || '',
    messages:richMessages,
    context,
    classification:result.classification || {},
    readiness:result.readiness || {},
    draftBrief:result.brief || result.draft_brief || {},
    linkedContexts,
    existingDraft
  };
}
async function prepareCoworkEmailThreadDraft({messageId='',threadId='',conversationId='',provider='',replyIntent='',sessionId='',workItemId=''}={}){
  const thread=await loadEmailThreadForCowork({messageId,threadId,conversationId,provider});
  if(!thread) throw new Error('VAL could not load the selected email thread. It did not substitute another conversation.');
  if(thread.existingDraft) return {draft:thread.existingDraft,alreadyPrepared:true,noExternalAction:true};
  const intent=String(replyIntent || '').trim();
  if(!intent) throw new Error('VAL needs the intended reply outcome before it can prepare a private draft.');
  const baseBrief=thread.draftBrief || {};
  const brief={
    ...baseBrief,
    must_include:[...new Set([...(Array.isArray(baseBrief.must_include) ? baseBrief.must_include : []),`Executive reply outcome: ${intent}`])]
  };
  const readiness={
    ...(thread.readiness || {}),
    status:'ready_for_review',
    missing_context:[],
    missingContext:[],
    approval_policy:'approval_required'
  };
  const prepared=await valExecutiveInbox.generateDraft({
    context:thread.context,
    classification:thread.classification || {},
    readiness,
    brief
  });
  if(!prepared?.draft?.body || prepared.status !== 'ready_for_review') throw new Error('VAL stopped the draft because it did not pass review-only quality checks. Nothing was sent or changed externally.');
  return {...prepared,noExternalAction:true,sessionId,workItemId};
}
