app.post('/api/homepage-cards/action',async(req,res)=>{
  try{
    const action=String(req.body.action||'').trim();
    const cardType=String(req.body.cardType||req.body.card_type||'homepage_card').trim();
    const item=req.body.item||{};
    if(!action)return res.status(400).json({ok:false,error:'Missing action'});
    const title=dashboardCleanText(req.body.title||item.title||item.name||'Homepage card action');
    const summary=dashboardCleanText(req.body.summary||item.summary||item.reason_it_matters||item.why||'');
    const sourceContext={source:'homepage_card',cardType,action,item:{id:item.id||'',source_type:item.source_type||item.sourceType||'',source_id:item.source_id||item.sourceId||'',target:item.target||null,title,summary}};
    let result={ok:true,action,cardType,status:'logged'};
    const taskActions=['create_task','create_follow_up_task','do_it_now','schedule_time','schedule_meeting','schedule_work_block','follow_up'];
    const draftActions=['draft_email','draft_response','draft_update','create_client_update','save_draft','edit_before_approving','summarize_project'];
    const decisionActions=['snooze','dismiss','ignore','not_important','not_useful','mark_signal_wrong','reject','approve','send_email','add_to_memory','mark_vip','watch_project','archive_project','resolve_loop','correct_association','attach_to_contact','attach_to_project','attach_evidence','add_to_project','update_contact','add_contact_note','update_project_status','move_opportunity','review_evidence'];
    const decisionStatus={
      snooze:'snoozed',
      dismiss:'dismissed',
      ignore:'ignored',
      not_important:'preference_logged',
      not_useful:'feedback_logged',
      mark_signal_wrong:'correction_logged',
      reject:'rejected_logged',
      approve:'approved_logged',
      send_email:'approval_required',
      add_to_memory:'memory_requested',
      mark_vip:'vip_logged',
      watch_project:'watch_logged',
      archive_project:'archive_requested',
      resolve_loop:'loop_resolution_logged',
      correct_association:'correction_logged',
      attach_to_contact:'attachment_requested',
      attach_to_project:'attachment_requested',
      attach_evidence:'attachment_requested',
      add_to_project:'attachment_requested',
      update_contact:'update_requested',
      add_contact_note:'note_requested',
      update_project_status:'update_requested',
      move_opportunity:'opportunity_update_requested',
      review_evidence:'evidence_review_logged'
    };
    const statusMessage={
      task_created:'Task created and linked to this card signal.',
      draft_created:'Draft prepared for review. Nothing was sent.',
      snoozed:'Snoozed. VAL will keep the source history.',
      dismissed:'Dismissed and logged.',
      ignored:'Ignored and logged.',
      preference_logged:'Preference logged. VAL will use it when ranking future cards.',
      feedback_logged:'Feedback logged. VAL will avoid treating similar items as useful without stronger evidence.',
      correction_logged:'Correction logged for review. VAL did not change source records automatically.',
      rejected_logged:'Rejection logged.',
      approved_logged:'Approval logged. External actions still require their dedicated approval flow.',
      approval_required:'Final send approval is required. Nothing was sent.',
      memory_requested:'Memory add request logged for review.',
      vip_logged:'VIP preference logged.',
      watch_logged:'Project watch preference logged.',
      archive_requested:'Archive request logged for review.',
      loop_resolution_logged:'Loop resolution logged for review.',
      attachment_requested:'Attachment request logged for review.',
      update_requested:'Update request logged for review.',
      note_requested:'Contact note request logged for review.',
      opportunity_update_requested:'Opportunity movement request logged for review.',
      evidence_review_logged:'Evidence review logged.'
    };
    const metadata=item.metadataJson||item.metadata||item.readinessJson||{};
    const artifact=item.preparedArtifact||item.prepared_artifact||metadata.preparedArtifact||metadata.prepared_artifact||{};
    const preparedArtifactKind=String(item.preparedArtifactKind||item.prepared_artifact_kind||artifact.kind||metadata.preparedArtifactKind||metadata.prepared_artifact_kind||'').trim();
    if(preparedArtifactKind&&['review_prepared_work','approve','edit_before_approving','reject'].includes(action)){
      const packet=valExternalActions.preparePacketFromPreparedArtifact?await valExternalActions.preparePacketFromPreparedArtifact(item):null;
      if(!packet)return res.status(400).json({ok:false,error:'Prepared work could not be mapped to an external action packet'});
      let packetResult=packet;
      let status='external_packet_ready';
      let message='Prepared-work packet is ready for review. No external action was taken.';
      if(action==='approve'){
        packetResult=await valExternalActions.approve(packet.id,{note:'Approved from prepared-work review surface. Local approval only.'});
        status='external_packet_approved_local_only';
        message='Approval recorded on the exact action packet. Nothing has been sent, published, scheduled, or changed externally.';
      }else if(action==='edit_before_approving'){
        packetResult=await valExternalActions.edit(packet.id,{note:'Edit requested from prepared-work review surface.'});
        status='external_packet_edit_requested';
        message='Packet is ready to refine before approval. No external action was taken.';
      }else if(action==='reject'){
        packetResult=await valExternalActions.reject(packet.id,{reason:'Declined from prepared-work review surface.'});
        status='external_packet_rejected';
        message='Prepared work was declined on the exact action packet. No external action was taken.';
      }
      await auditLog({req,action:'homepage_prepared_work_packet_review',resourceType:'val_external_action_packet',resourceId:packet.id,metadata:{cardType,homepageAction:action,preparedArtifactKind,packetStatus:packetResult?.status,externalActionTaken:false,executionAvailable:false},success:true}).catch(()=>{});
      return res.json({ok:true,action,cardType,status,message,packet:packetResult,packet_id:packet.id,no_external_action:true,execution_available:false});
    }
    if(taskActions.includes(action)){
      const dueDate=req.body.dueDate||new Date(Date.now()+2*24*60*60*1000).toISOString();
      const defaultTitle=action==='schedule_meeting'?`Schedule meeting: ${title}`:action==='schedule_work_block'||action==='schedule_time'?`Schedule time: ${title}`:action==='follow_up'||action==='create_follow_up_task'?`Follow up: ${title}`:title||'Review VAL signal';
      const task={id:uuid('task'),title:req.body.taskTitle||defaultTitle,contactName:item.name||'',contactId:item.contact_id||item.contactId||'',dueDate,priority:req.body.priority||(/highest|risk|urgent|important/i.test(String(item.impact||item.priorityBand||summary))?'high':'medium'),notes:req.body.notes||[summary,item.reason_it_matters?`Why it matters: ${item.reason_it_matters}`:'',`Created from ${cardType}. Action: ${action}.`].filter(Boolean).join('\n\n'),details:[{text:`Created from ${cardType}: ${action}`,ts:new Date().toISOString(),sourceContext}],completed:false,createdAt:new Date().toISOString(),source:'homepage_card',sourceCardType:cardType,sourceItemId:item.id||item.source_id||''};
      await saveTask(task);
      result={...result,status:'task_created',message:statusMessage.task_created,task};
    }else if(draftActions.includes(action)){
      const subject=req.body.subject||(
        action==='summarize_project'?`Project summary: ${title}`:
        action==='create_client_update'?`Client update: ${title}`:
        action==='draft_response'?`Response draft: ${title}`:
        title||'VAL prepared draft'
      );
      const body=req.body.body||[
        action==='summarize_project'?'Project summary draft from VAL signal:':'Draft from VAL signal:',
        '',
        summary||title,
        item.reason_it_matters?`\nWhy it matters: ${item.reason_it_matters}`:'',
        '\nPrepared for human review. Nothing has been sent.'
      ].filter(Boolean).join('\n');
      const draft=await saveInternalDraft({draftType:'homepage_card_action',provider:'internal',subject,body,sourceContext});
      result={...result,status:'draft_created',message:statusMessage.draft_created,draft};
    }else if(decisionActions.includes(action)){
      const until=action==='snooze'?(req.body.until||new Date(Date.now()+7*24*60*60*1000).toISOString()):'';
      await saveMemoryItem({kind:'homepage_card_decision',summary:`${action}: ${title}`,rawText:JSON.stringify({action,cardType,item,until,note:req.body.note||''}),importance:/approve|mark_vip|watch_project|add_to_memory/i.test(action)?3:1,metadata:{source:'homepage_card',cardType,action,until,itemId:item.id||'',sourceType:item.source_type||item.sourceType||'',sourceId:item.source_id||item.sourceId||''}});
      const status=decisionStatus[action]||'decision_logged';
      result={...result,status,message:statusMessage[status]||'Decision logged.',until};
    }else{
      return res.status(400).json({ok:false,error:'Unsupported homepage card action',action});
    }
    await auditLog({req,action:'homepage_card_action',resourceType:cardType,resourceId:item.id||item.source_id||'',metadata:{action,status:result.status,title},success:true}).catch(()=>{});
    res.json(result);
  }catch(e){
    await auditLog({req,action:'homepage_card_action_failed',resourceType:'homepage_card',metadata:{error:e.message,body:req.body},success:false}).catch(()=>{});
    res.status(500).json({ok:false,error:e.message});
  }
});
app.post('/api/val/intelligence',async(req,res)=>{
  try{
    const action=req.body.action||'what_now',query=req.body.query||'',dashboard=req.body.dashboard||{},tasks=Array.isArray(req.body.tasks)?req.body.tasks:[];
    if(DEMO_MODE){const s=demoState(req,res);return res.json({ok:true,action,content:demoIntelligenceResponse(action,query,s),demo:true});}
    const uploadedDocs=await uploadedValDocumentContextForQuery(`${action} ${query}`).catch(e=>`Uploaded VAL document lookup failed: ${e.message}`);
    const [memory,ghlContext,googleDocs]=await Promise.all([
      recentMemoryContext(`${action} ${query}`),
      ghlPlatformContext(`${action} ${query} ${JSON.stringify(dashboard).slice(0,2500)}`,dashboard),
      uploadedDocs?Promise.resolve(''):googleDocsContextForQuery(`${action} ${query}`).catch(e=>`Google Docs lookup failed: ${e.message}`)
    ]);
    const system=[VAL_SYSTEM_PROMPT,'Use uploaded VAL document source text, saved memory, Google Docs source text, dashboard data, platform-wide GHL MCP context, task state, and the requested action. Be specific, practical, and decisive. If uploaded VAL document source text is present, treat it as visible source material and do not ask for Drive, Docs, or pasted chunks. Do not begin with source/upload/readability status unless the user explicitly asks whether you can read or access the manuscript.','For Michele book/editor responses, every time you name work the user should do, include a "To-do list" section with only the 1 to 5 highest-priority new or updated actions. Do not repeat the entire existing task list. Each to-do must be one concrete action line with enough context to understand why it matters, such as chapter, section, reason, or source. Do not leave recommendations only in prose. For priority/next-step requests, keep the whole chat answer short and let the task board hold the longer list.',memory?'Relevant saved memory:\n'+memory:'',uploadedDocs?'Relevant uploaded VAL document source:\n'+uploadedDocs:'',googleDocs?'Relevant Google Docs source:\n'+googleDocs:'',ghlContext?'Platform-wide GHL MCP context:\n'+ghlContext:''].filter(Boolean).join('\n\n');
    const user=['Requested VAL action: '+action,'Instruction: '+actionPrompt(action),query?'User query: '+query:'','Dashboard JSON: '+JSON.stringify(dashboard).slice(0,9000),'Tasks JSON: '+JSON.stringify(tasks).slice(0,9000)].filter(Boolean).join('\n\n');
    const actionMaxTokens=/^(book_next_steps|editorial_next_steps)$/i.test(action)?650:1800;
    const content=await callValModel({system,user,maxTokens:actionMaxTokens,temperature:0.35});
    const createdTasks=await persistAutoTasksFromValResponse({content,userQuery:query||action,action,source:'val_intelligence'}).catch(e=>{console.warn('Auto task capture failed:',e.message);return [];});
    res.json({ok:true,action,content,createdTasks,ghlContextAvailable:!!ghlContext});
  }catch(e){res.status(500).json({error:e.message});}
});
app.post('/api/val/chat',async(req,res)=>{
  try{
    const messages=Array.isArray(req.body.messages)?req.body.messages:[],lastUser=[...messages].reverse().find(m=>m.role==='user')?.content||'',memoryQuery=messages.slice(-10).map(m=>m.content||'').join('\n').slice(-6000),dashboard=req.body.dashboard||{};
    const projectContext=req.body.projectContext&&typeof req.body.projectContext==='object'?req.body.projectContext:null;
    const conversationId=String(req.body.conversationId||'').trim()||uuid('chat');
    const conversationTitle=String(req.body.title||lastUser||'New conversation').trim().slice(0,120)||'New conversation';
    async function sendChat(content,extra={}){
      let saved=null,saveWarning='';
      const fullMessages=messages.concat({role:'assistant',content});
      try{
        if(!DEMO_MODE&&process.env.DATABASE_URL&&!pgPool) throw new Error('Chat could not be saved because Postgres is not connected. In Railway, confirm your Postgres service is attached and DATABASE_URL exists in Variables.');
        saved=await saveConversation({id:conversationId,title:conversationTitle,source:req.body.channel||'chat',messages:fullMessages,metadata:{channel:req.body.channel||'chat',savedBy:'chat_route',projectContext:projectContext||undefined,projectId:projectContext?.projectId||'',projectName:projectContext?.projectName||''}});
        if(projectContext?.projectId||projectContext?.projectName){
          const projectChatMemory=await saveMemoryItem({
            kind:'project_chat_context',
            summary:'Project Co-Work: '+(projectContext.projectName||projectContext.projectId||conversationTitle),
            rawText:fullMessages.map(m=>`${m.role||'user'}: ${m.content||''}`).join('\n\n').slice(0,12000),
            importance:3,
            metadata:{source:'hearth_cowork',conversationId:saved?.id||conversationId,projectId:projectContext.projectId||'',projectName:projectContext.projectName||'',projectProfileId:projectContext.projectProfileId||'',noExternalAction:true}
          }).catch(()=>{});
          await valReviewUpdates.createProjectSourceInterpretation({
            projectId:projectContext.projectId||projectContext.projectProfileId||projectContext.projectName,
            projectName:projectContext.projectName||projectContext.projectId||'Project',
            sourceType:'project_chat_context',
            sourceId:projectChatMemory?.id||saved?.id||conversationId,
            sourceTitle:conversationTitle,
            summary:'Project Co-Work context captured for review: '+(lastUser||conversationTitle),
            rawText:fullMessages.map(m=>`${m.role||'user'}: ${m.content||''}`).join('\n\n').slice(0,12000),
            confidence:0.72
          }).catch(()=>{});
        }
      }catch(saveError){
        saveWarning=saveError.message||'Chat could not be saved because Postgres is not connected. In Railway, confirm your Postgres service is attached and DATABASE_URL exists in Variables.';
      }
      return res.json({message:{role:'assistant',content},conversationId:saved?.id||conversationId,saved:!saveWarning,saveWarning,...extra});
    }
    if(DEMO_MODE){const s=demoState(req,res);return sendChat(demoChatResponse(lastUser,s),{demo:true});}
    const presenceMode=presenceModeEnabledFromRequest(req),presenceIntent=presenceMode?classifyPresenceIntent(lastUser,{currentSession:true}):null;
    if(presenceIntent?.requiresConfirmation){
      return sendChat([
        'I can prepare that, but I need your approval before anything external happens.',
        '',
        `Detected action: ${presenceIntent.action.replace(/_/g,' ')}`,
        presenceIntent.allowedPrivatePreparations.length?`I can do the private prep first: ${presenceIntent.allowedPrivatePreparations.join(', ').replace(/_/g,' ')}.`:'',
        '',
        'Say “draft it first” or “yes, send/book/share it now” when you want to approve the next step.'
      ].filter(Boolean).join('\n'),{presenceIntent});
    }
    if(/\b(show|list|find)\b[\s\S]{0,40}\bunscheduled tasks|open loops\b/i.test(lastUser)){
      const loops=await openLoopsSummary();
      const lines=(loops.unscheduled||[]).slice(0,10).map((t,i)=>`${i+1}. ${t.title}${t.dueDate?` — due ${new Date(t.dueDate).toLocaleDateString()}`:''}`).join('\n')||'No unscheduled open tasks found.';
      return sendChat(`Open loops: ${loops.openCount} open, ${loops.unscheduledCount} unscheduled, ${loops.overdueCount} overdue.\n\n${lines}`,{openLoops:loops});
    }
    if(/\b(calendarize|schedule time|put .*calendar|block time)\b/i.test(lastUser)&&/\btask|tasks|open loops|follow[- ]?up/i.test(lastUser)){
      const loops=await openLoopsSummary();
      const task=(loops.unscheduled||[])[0];
      if(!task)return sendChat('I do not see any unscheduled open tasks right now.',{openLoops:loops});
      const suggestedSlots=await suggestTaskSlots(task).catch(()=>[]);
      const slotLines=suggestedSlots.slice(0,3).map((s,i)=>`${i+1}. ${s.label}`).join('\n');
      return sendChat(`I found the next unscheduled task: ${task.title}.\n\nSuggested protected work blocks:\n${slotLines||'No safe slot found yet.'}\n\nOpen Tasks and press Calendarize to confirm a private busy block with no attendees or meeting link.`,{taskScheduling:{task,suggestedSlots}});
    }
    if(inboxCommandIntent(lastUser)){
      const inbox=await runInboxCommand(lastUser,{maxResults:5});
      const sourceLines=(inbox.sources||[]).slice(0,5).map((email,i)=>`${i+1}. ${email.subject||'(No subject)'} — ${email.from?.name||email.from?.email||'unknown'} — ${email.date?new Date(email.date).toLocaleString():''}\n   ${email.snippet||''}`).join('\n');
      return sendChat([inbox.answer,sourceLines?'\nSources:\n'+sourceLines:'',inbox.needsChoice?'\nIf you want me to act on one, tell me which number.':''].filter(Boolean).join('\n'),{inboxCommand:inbox});
    }
    if(isGoallTestContactRequest(lastUser)){
      const result=await createOrUpdateGoallTestContact();
      return sendChat(goallTestContactSummary(result),{ghlContact:result});
    }
    const inferredGhlAction=await inferGhlActionFromChat(lastUser);
    if(inferredGhlAction){
      const packet=saveValOsExternalActionPacket(buildGhlExternalActionPacket(inferredGhlAction,lastUser));
      return sendChat([
        'I prepared the CRM action packet and need one approval before I touch the external system.',
        '',
        packet.willDo,
        '',
        'Approve it below and I will do exactly this, then show a receipt. Until then, this is prepared Co-Work only.'
      ].join('\n'),{externalActionPacket:packet,ghlMcpCoworkActionPacket:true,noExternalAction:true});
    }
    if(isGoogleDocRewriteRequest(lastUser)){
      try{
        const result=await rewriteGoogleDocChapter({query:lastUser,mode:'create'});
        const scopeLabel=result.source.scope==='chapter'?'chapter':'document';
        const content=[
          `Done. I rewrote the full ${scopeLabel} from ${result.source.title} as a new Google Doc.`,
          '',
          `Source: ${result.source.url}`,
          `Rewrite: ${result.output.url}`,
          '',
          `I kept the full rewrite out of chat so you can review and edit it in Docs.`
        ].join('\n');
        return sendChat(content,{googleDocRewrite:result});
      }catch(e){
        if(/auth|required|scope|reconnect/i.test(e.message)){
          return sendChat('I can use the memoir already uploaded into VAL as the source. Google only needs to be reconnected so I can create the rewritten Google Doc output. Open Integration Status, reconnect Google, and approve the Drive/Docs permissions.');
        }
        return sendChat(`I tried to rewrite it from the uploaded VAL memoir or Google Docs, but I could not find a readable matching document yet: ${e.message}\n\nUse the exact uploaded file title, Google Doc title, or Google Doc URL, then ask me to rewrite it.`);
      }
    }
    const availabilityDoc=await readValUploadedRewriteSource({query:lastUser+'\n'+memoryQuery}).catch(()=>null);
    if(availabilityDoc&&/\b(can you|could you|do you|are you able to)\b[\s\S]{0,80}\b(read|see|access|open)\b/i.test(lastUser)&&/\b(manuscript|memoir|book|document|doc|draft)\b/i.test(lastUser)){
      return sendChat([
        `Yes. I can read the manuscript already uploaded into VAL.`,
        '',
        `Source: ${availabilityDoc.title}`,
        `Readable characters: ${availabilityDoc.text.length}`,
        '',
        `Google Drive is only needed if you want me to create or update a Google Doc output. For reading and editorial review, I can use the uploaded VAL manuscript.`
      ].join('\n'));
    }
    const [uploadedDocs,linkedAttachmentDocs]=await Promise.all([
      uploadedValDocumentContextForQuery(lastUser+'\n'+memoryQuery).catch(e=>`Uploaded VAL document lookup failed: ${e.message}`),
      linkedGmailAttachmentContextForQuery(lastUser+'\n'+memoryQuery,projectContext).catch(error=>{
        console.warn('Linked Gmail attachment lookup failed:',error.message);
        return '';
      })
    ]);
    const [memory,ghlContext,googleDocs,executiveBriefing]=await Promise.all([
      recentMemoryContext(lastUser+'\n'+memoryQuery),
      ghlPlatformContext(lastUser+'\n'+memoryQuery,dashboard),
      uploadedDocs||linkedAttachmentDocs?Promise.resolve(''):googleDocsContextForQuery(lastUser+'\n'+memoryQuery).catch(e=>`Google Docs lookup failed: ${e.message}`),
      isBookEditorProject()?Promise.resolve(null):buildExecutiveBriefing().catch(()=>null)
    ]);
    const babyStudioContext=await babyStudioPromptContext();
    const system=[VAL_SYSTEM_PROMPT,babyStudioContext?'Dashboard Studio settings:\n'+babyStudioContext:'',presenceMode?presenceContractPrompt():'','Use dashboard context, Executive Briefing source context, linked VAL attachment source text, uploaded VAL document source text, Google Docs source text, platform-wide GHL MCP context, task state, project context, relationship context, and saved memory when relevant. Do not pretend to know facts that are not present. When project context is supplied, keep the answer organized around that project and do not flatten it into generic chat history.','When Relevant linked VAL attachment source is present, use it directly as the requested document. Do not say the attachment is unavailable, and do not ask for Google Drive, Google Docs, pasted chunks, or a re-upload. Do not begin ordinary document-review responses with source/access status.','When Relevant uploaded VAL document source is present, use it directly. Do not ask for Google Drive, Google Docs, pasted chunks, or uploads. Say plainly that the manuscript is available in VAL only if the user asks whether you can read or access it. Do not begin ordinary editorial responses with source/upload/readability status.','For Michele book/editor responses, every time you name work the user should do, include a "To-do list" section with only the 1 to 5 highest-priority new or updated actions. Do not repeat the entire existing task list. Each to-do must be one concrete action line with enough context to understand why it matters, such as chapter, section, reason, or source. Do not leave recommendations only in prose. For priority/next-step requests, keep the whole chat answer short and let the task board hold the longer list.','When Recent saved VAL memory contains knowledge_document, processed_transcript, or transcript entries, the text after the colon is available source content. Use it directly. Do not say the document or transcript text is not visible unless no relevant memory entries are present.','When Relevant Google Docs source is present, use it directly. Do not ask the user to paste the document or send it in chunks. If Google Docs says reconnect is required, tell the user to reconnect Google from Integration Status and approve Drive/Docs permissions.','When Platform-wide GHL MCP context is present, use GHL contacts, opportunities, tasks, conversations, notes, and call transcripts as current CRM source context.',projectContext?'Active project context:\n'+JSON.stringify(projectContext,null,2).slice(0,4000):'',executiveBriefing?'Executive Briefing source context:\n'+executiveBriefingChatContext(executiveBriefing):'',memory?'Recent saved VAL memory:\n'+memory:'',linkedAttachmentDocs?'Relevant linked VAL attachment source:\n'+linkedAttachmentDocs:'',uploadedDocs?'Relevant uploaded VAL document source:\n'+uploadedDocs:'',googleDocs?'Relevant Google Docs source:\n'+googleDocs:'',ghlContext?'Platform-wide GHL MCP context:\n'+ghlContext:''].filter(Boolean).join('\n\n');
    const content=await callOpenAIResponses({system,messages,maxTokens:1900,temperature:0.7});
    const finalContent=content||'I could not process that.';
    const createdTasks=await persistAutoTasksFromValResponse({content:finalContent,userQuery:lastUser,action:'chat',source:'val_chat'}).catch(e=>{console.warn('Auto task capture failed:',e.message);return [];});
    return sendChat(finalContent,{createdTasks,ghlContextAvailable:!!ghlContext});
  }catch(e){
    const raw=e.message||'';
    const message=/OPENAI_KEY not configured|OPENAI_API_KEY|api key/i.test(raw)
      ? 'Chat is not working because your AI API key is missing. Go to Railway → Variables and add OPENAI_API_KEY. Then redeploy Baby VAL.'
      : raw;
    res.status(500).json({error:message});
  }
});

async function extractUploadedText(file){
  const name=file.originalname||'uploaded-file', mime=file.mimetype||'', ext=path.extname(name).toLowerCase();
  if(mime.startsWith('text/')||['.txt','.md','.markdown','.html','.htm','.json','.csv','.tsv'].includes(ext)) return file.buffer.toString('utf8');
  if(mime==='application/pdf'||ext==='.pdf') return (await pdfParse(file.buffer)).text||'';
  if(mime==='application/vnd.openxmlformats-officedocument.wordprocessingml.document'||ext==='.docx') return (await mammoth.extractRawText({buffer:file.buffer})).value||'';
  if(mime==='application/msword'||ext==='.doc'){
    const tempDir=await fs.promises.mkdtemp(path.join(os.tmpdir(),'val-doc-upload-'));
    const inputPath=path.join(tempDir,name.replace(/[^\w.-]+/g,'_')||'upload.doc');
    const outputPath=inputPath.replace(/\.doc$/i,'.txt')+'.txt';
    try{
      await fs.promises.writeFile(inputPath,file.buffer);
      await execFileAsync('/usr/bin/textutil',['-convert','txt','-output',outputPath,inputPath],{timeout:15000});
      return await fs.promises.readFile(outputPath,'utf8');
    }catch(e){
      throw new Error('Legacy .doc files could not be read on this server. Save the file as .docx or .txt and upload it again.');
    }finally{
      await fs.promises.rm(tempDir,{recursive:true,force:true}).catch(()=>{});
    }
  }
  throw new Error('Unsupported file type. Upload TXT, DOC, DOCX, MD, HTML, JSON, CSV, PDF, or TSV.');
}
app.post('/api/val/files',upload.any(),async(req,res)=>{
  try{
    const files=(req.files||[]).filter(Boolean);
    if(!files.length)return res.status(400).json({error:'Missing file'});
    const savedFiles=[];
    for(const file of files.slice(0,10)){
      const text=(await extractUploadedText(file)).trim();
      if(!text) throw new Error(`No readable text found in ${file.originalname}`);
      const inferredDocType=inferBookDocTypeFromName([req.body.title,file.originalname].filter(Boolean).join(' '),req.body.docType||'knowledge_document');
      const isTranscriptUpload=isUploadedTranscriptDocType(inferredDocType);
      const metadata={
        fileName:file.originalname,
        mimeType:file.mimetype,
        size:file.size,
        project:req.body.project||CLIENT_CONFIG.projectName||CLIENT_CONFIG.brandName||'',
        client:req.body.client||CLIENT_CONFIG.clientName||'',
        docType:inferredDocType,
        chapterNumber:req.body.chapterNumber||'',
        chapterTitle:req.body.chapterTitle||'',
        canonicalManuscript:inferredDocType==='manuscript',
        projectType:CLIENT_CONFIG.projectType||'',
        uploadedVia:req.body.uploadedVia||'val_file_upload'
      };
      const saved=await saveTranscript({
        type:isTranscriptUpload?'processed_transcript':'knowledge_document',
        title:req.body.title||file.originalname,
        transcript:text,
        rawText:text,
        timestamp:new Date().toISOString(),
        source:isTranscriptUpload?'val_file_upload_transcript':'val_file_upload',
        importance:isBookEditorProject()?4:3,
        metadata
      });
      let processed=null,processingError='';
      if(isTranscriptUpload&&String(req.body.processTranscript||'true')!=='false'){
        try{
          processed=await processTranscriptPayload({
            source:'val_file_upload_transcript',
            title:req.body.title||file.originalname,
            transcript:text,
            rawText:text,
            savedTranscriptId:saved.id,
            timestamp:new Date().toISOString(),
            metadata
          });
        }catch(e){
          processingError=e.message||String(e);
          await updateTranscriptIndexStatus(saved.id,{processingStatus:'failed',summaryStatus:'pending'}).catch(()=>{});
        }
      }
      await auditLog({req,action:isTranscriptUpload?'val_file_uploaded_transcript':'val_file_uploaded',resourceType:isTranscriptUpload?'transcript':'file',resourceId:saved?.id||'',metadata:{fileName:file.originalname,docType:inferredDocType,uploadedVia:metadata.uploadedVia,characters:text.length,processed:!!processed,processingError},success:!processingError}).catch(()=>{});
      savedFiles.push({...saved,fileName:file.originalname,chars:text.length,metadata,docType:inferredDocType,processed:!!processed,processingError,counts:processed?.counts||null});
    }
    res.json({ok:true,...savedFiles[0],files:savedFiles,fileName:savedFiles[0]?.fileName,chars:savedFiles.reduce((n,f)=>n+(f.chars||0),0)});
  }catch(e){res.status(500).json({error:e.message});}
});

